package com.harrystyles.drystreaktracker.cosmetic;

import com.harrystyles.drystreaktracker.DryStreakTrackerConfig;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Set;

import javax.inject.Inject;
import javax.inject.Singleton;

import lombok.extern.slf4j.Slf4j;

import net.runelite.api.AnimationController;
import net.runelite.api.Client;
import net.runelite.api.JagexColor;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.Tile;
import net.runelite.api.TileItem;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ItemDespawned;
import net.runelite.api.events.ItemQuantityChanged;
import net.runelite.api.events.ItemSpawned;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.events.ConfigChanged;

@Slf4j
@Singleton
public class SmokeLootbeamManager {
    private static final int SMOKE_MODEL_ID = 50683;
    private static final int SMOKE_ANIMATION_ID = 10727;

    /*
     * Ground item events and loot detection events should normally
     * occur during the same tick or immediately beside one another.
     *
     * Keeping only a very small tick window prevents unrelated
     * world spawns from being matched later.
     */
    private static final int MATCH_WINDOW_TICKS = 1;

    private final Client client;
    private final ClientThread clientThread;
    private final DryStreakTrackerConfig config;

    /*
     * Tiles which currently contain one or more confirmed
     * player-earned tracked drops.
     */
    private final Map<WorldPoint, SmokeTileState> activeSmoke = new HashMap<>();

    /*
     * Tracked drops confirmed by LootDetectionService but whose
     * ground ItemSpawned/ItemQuantityChanged event may not have
     * been observed yet.
     */
    private final List<PendingEarnedDrop> pendingEarnedDrops = new ArrayList<>();

    /*
     * Ground items which appeared recently but have not yet been
     * confirmed by LootDetectionService as player-earned.
     *
     * This handles RuneLite firing ItemSpawned before
     * NpcLootReceived.
     */
    private final List<RecentGroundItem> recentGroundItems = new ArrayList<>();

    private Model cachedSmokeModel;
    private SmokeLootbeamColor cachedSmokeColor;

    @Inject
    public SmokeLootbeamManager(Client client, ClientThread clientThread, DryStreakTrackerConfig config) {
        this.client = client;
        this.clientThread = clientThread;
        this.config = config;
    }

    /**
     * Called by LootDetectionService after a tracked NPC loot event
     * has been successfully recorded.
     *
     * These item IDs are known to have actually been earned by the
     * player, so only they are eligible for Smoke Lootbeams.
     */
    public void markEarnedDrops(Set<Integer> itemIds) {
        if (itemIds == null || itemIds.isEmpty()) {
            return;
        }

        cleanupMatchingState();

        int currentTick = client.getTickCount();

        for (Integer itemId : itemIds) {
            if (itemId == null || itemId <= 0) {
                continue;
            }

            /*
             * ItemSpawned may already have happened before
             * NpcLootReceived.
             *
             * If so, match the confirmed earned item against the
             * recently observed ground item immediately.
             */
            RecentGroundItem recentGroundItem = findRecentGroundItem(itemId, currentTick);

            if (recentGroundItem != null) {
                addEarnedItem(recentGroundItem.tile, itemId);

                recentGroundItems.remove(recentGroundItem);

                continue;
            }

            /*
             * Otherwise remember the earned item briefly and let the
             * upcoming ItemSpawned or ItemQuantityChanged event match it.
             */
            pendingEarnedDrops.add(new PendingEarnedDrop(itemId, currentTick));
        }
    }

    public void handleItemSpawned(ItemSpawned event) {
        if (event == null || event.getItem() == null || event.getTile() == null) {
            return;
        }

        cleanupMatchingState();

        TileItem item = event.getItem();
        int itemId = item.getId();
        int currentTick = client.getTickCount();

        PendingEarnedDrop pendingDrop = findPendingEarnedDrop(itemId, currentTick);

        if (pendingDrop != null) {
            pendingEarnedDrops.remove(pendingDrop);

            addEarnedItem(event.getTile(), itemId);

            return;
        }

        /*
         * Do not create smoke yet.
         *
         * ItemSpawned can represent static world spawns,
         * other players' visible loot, or unrelated items.
         *
         * Remember the item briefly in case LootDetectionService
         * confirms it as ours later in the same matching window.
         */
        recentGroundItems.add(new RecentGroundItem(event.getTile(), itemId, currentTick));
    }

    public void handleItemDespawned(ItemDespawned event) {
        if (event == null || event.getItem() == null || event.getTile() == null) {
            return;
        }

        int itemId = event.getItem().getId();

        removeRecentGroundItem(event.getTile(), itemId);

        removeEarnedItem(event.getTile(), itemId);
    }

    public void handleItemQuantityChanged(ItemQuantityChanged event) {
        if (event == null || event.getItem() == null || event.getTile() == null) {
            return;
        }

        cleanupMatchingState();

        int itemId = event.getItem().getId();
        int currentTick = client.getTickCount();

        /*
         * RuneLite may increase an existing ground stack instead
         * of firing ItemSpawned.
         */
        if (event.getNewQuantity() > event.getOldQuantity()) {
            PendingEarnedDrop pendingDrop = findPendingEarnedDrop(itemId, currentTick);

            if (pendingDrop != null) {
                pendingEarnedDrops.remove(pendingDrop);

                addEarnedItem(event.getTile(), itemId);

                return;
            }

            /*
             * The quantity-change event may arrive before the
             * corresponding loot detection event.
             */
            recentGroundItems.add(new RecentGroundItem(event.getTile(), itemId, currentTick));

            return;
        }

        if (event.getNewQuantity() <= 0) {
            removeRecentGroundItem(event.getTile(), itemId);

            removeEarnedItem(event.getTile(), itemId);
        }
    }

    public void handleConfigChanged(ConfigChanged event) {
        if (event == null || !"drystreaktracker".equals(event.getGroup())) {
            return;
        }

        if (!"enableSmokeLootbeams".equals(event.getKey())
                && !"smokeLootbeamColor".equals(event.getKey())) {
            return;
        }

        clientThread.invokeLater(() -> {
            cachedSmokeModel = null;
            cachedSmokeColor = null;

            if (!config.enableSmokeLootbeams()) {
                deactivateAllSmokeObjects();

                return;
            }

            rebuildSmokeObjects();
        });
    }

    public void clear() {
        for (SmokeTileState state : activeSmoke.values()) {
            deactivateSmokeObject(state);
        }

        activeSmoke.clear();
        pendingEarnedDrops.clear();
        recentGroundItems.clear();

        cachedSmokeModel = null;
        cachedSmokeColor = null;
    }

    private PendingEarnedDrop findPendingEarnedDrop(int itemId, int currentTick) {
        for (PendingEarnedDrop pendingDrop : pendingEarnedDrops) {
            if (pendingDrop == null || pendingDrop.itemId != itemId) {
                continue;
            }

            if (currentTick - pendingDrop.tick <= MATCH_WINDOW_TICKS) {
                return pendingDrop;
            }
        }

        return null;
    }

    private RecentGroundItem findRecentGroundItem(int itemId, int currentTick) {
        for (RecentGroundItem recentGroundItem : recentGroundItems) {
            if (recentGroundItem == null || recentGroundItem.itemId != itemId) {
                continue;
            }

            if (currentTick - recentGroundItem.tick <= MATCH_WINDOW_TICKS) {
                return recentGroundItem;
            }
        }

        return null;
    }

    private void cleanupMatchingState() {
        int currentTick = client.getTickCount();

        Iterator<PendingEarnedDrop> pendingIterator = pendingEarnedDrops.iterator();

        while (pendingIterator.hasNext()) {
            PendingEarnedDrop pendingDrop = pendingIterator.next();

            if (pendingDrop == null || currentTick - pendingDrop.tick > MATCH_WINDOW_TICKS) {
                pendingIterator.remove();
            }
        }

        Iterator<RecentGroundItem> recentIterator = recentGroundItems.iterator();

        while (recentIterator.hasNext()) {
            RecentGroundItem recentGroundItem = recentIterator.next();

            if (recentGroundItem == null || currentTick - recentGroundItem.tick > MATCH_WINDOW_TICKS) {
                recentIterator.remove();
            }
        }
    }

    private void removeRecentGroundItem(Tile tile, int itemId) {
        if (tile == null || itemId <= 0) {
            return;
        }

        WorldPoint worldPoint = tile.getWorldLocation();

        if (worldPoint == null) {
            return;
        }

        Iterator<RecentGroundItem> iterator = recentGroundItems.iterator();

        while (iterator.hasNext()) {
            RecentGroundItem recentGroundItem = iterator.next();

            if (recentGroundItem == null
                    || recentGroundItem.itemId != itemId
                    || recentGroundItem.tile == null) {
                continue;
            }

            WorldPoint recentWorldPoint = recentGroundItem.tile.getWorldLocation();

            if (worldPoint.equals(recentWorldPoint)) {
                iterator.remove();
            }
        }
    }

    private void addEarnedItem(Tile tile, int itemId) {
        if (tile == null || itemId <= 0) {
            return;
        }

        WorldPoint worldPoint = tile.getWorldLocation();

        if (worldPoint == null) {
            return;
        }

        SmokeTileState state = activeSmoke.get(worldPoint);

        if (state == null) {
            state = new SmokeTileState(tile.getLocalLocation(), tile.getPlane());

            activeSmoke.put(worldPoint, state);
        }

        state.itemIds.add(itemId);

        if (config.enableSmokeLootbeams() && state.smokeObject == null) {
            state.smokeObject = createSmokeObject(state.localPoint, state.plane);
        }
    }

    private void removeEarnedItem(Tile tile, int itemId) {
        if (tile == null || itemId <= 0) {
            return;
        }

        WorldPoint worldPoint = tile.getWorldLocation();

        if (worldPoint == null) {
            return;
        }

        SmokeTileState state = activeSmoke.get(worldPoint);

        if (state == null) {
            return;
        }

        state.itemIds.remove(itemId);

        if (!state.itemIds.isEmpty()) {
            return;
        }

        deactivateSmokeObject(state);

        activeSmoke.remove(worldPoint);
    }

    private RuneLiteObject createSmokeObject(LocalPoint localPoint, int plane) {
        if (localPoint == null) {
            return null;
        }

        Model model = getSmokeModel();

        if (model == null) {
            return null;
        }

        AnimationController animationController = new AnimationController(client, SMOKE_ANIMATION_ID);

        animationController.setOnFinished(AnimationController::loop);

        RuneLiteObject smokeObject = client.createRuneLiteObject();

        smokeObject.setModel(model);
        smokeObject.setAnimationController(animationController);
        smokeObject.setLocation(localPoint, plane);
        smokeObject.setActive(true);

        return smokeObject;
    }

    private Model getSmokeModel() {
        SmokeLootbeamColor smokeColor = config.smokeLootbeamColor();

        if (smokeColor == null) {
            smokeColor = SmokeLootbeamColor.PURPLE;
        }

        if (cachedSmokeModel != null && cachedSmokeColor == smokeColor) {
            return cachedSmokeModel;
        }

        ModelData modelData = client.loadModelData(SMOKE_MODEL_ID);

        if (modelData == null) {
            log.warn("Unable to load Smoke Lootbeam model {}", SMOKE_MODEL_ID);

            return null;
        }

        modelData = modelData.cloneColors();

        short[] faceColors = modelData.getFaceColors();

        if (faceColors != null) {
            for (short originalColor : faceColors) {
                int saturation = JagexColor.unpackSaturation(originalColor);
                int luminance = JagexColor.unpackLuminance(originalColor);

                short replacementColor = JagexColor.packHSL(smokeColor.getHue(), saturation, luminance);

                modelData.recolor(originalColor, replacementColor);
            }
        }

        cachedSmokeModel = modelData.light(
                ModelData.DEFAULT_AMBIENT,
                ModelData.DEFAULT_CONTRAST,
                ModelData.DEFAULT_X,
                ModelData.DEFAULT_Y,
                ModelData.DEFAULT_Z
        );

        cachedSmokeColor = smokeColor;

        return cachedSmokeModel;
    }

    private void rebuildSmokeObjects() {
        for (SmokeTileState state : activeSmoke.values()) {
            deactivateSmokeObject(state);

            state.smokeObject = createSmokeObject(state.localPoint, state.plane);
        }
    }

    private void deactivateAllSmokeObjects() {
        for (SmokeTileState state : activeSmoke.values()) {
            deactivateSmokeObject(state);
        }
    }

    private void deactivateSmokeObject(SmokeTileState state) {
        if (state == null || state.smokeObject == null) {
            return;
        }

        state.smokeObject.setActive(false);
        state.smokeObject = null;
    }

    private static class PendingEarnedDrop {
        private final int itemId;
        private final int tick;

        private PendingEarnedDrop(int itemId, int tick) {
            this.itemId = itemId;
            this.tick = tick;
        }
    }

    private static class RecentGroundItem {
        private final Tile tile;
        private final int itemId;
        private final int tick;

        private RecentGroundItem(Tile tile, int itemId, int tick) {
            this.tile = tile;
            this.itemId = itemId;
            this.tick = tick;
        }
    }

    private static class SmokeTileState {
        private final LocalPoint localPoint;
        private final int plane;
        private final Set<Integer> itemIds = new HashSet<>();

        private RuneLiteObject smokeObject;

        private SmokeTileState(LocalPoint localPoint, int plane) {
            this.localPoint = localPoint;
            this.plane = plane;
        }
    }
}

package com.harrystyles.drystreaktracker.cosmetic;

public enum SmokeLootbeamColor {
    PURPLE("Purple", 52),
    RED("Red", 0),
    ORANGE("Orange", 5),
    YELLOW("Yellow", 10),
    GREEN("Green", 21),
    CYAN("Cyan", 32),
    BLUE("Blue", 42),
    PINK("Pink", 58);

    private final String displayName;
    private final int hue;

    SmokeLootbeamColor(String displayName, int hue) {
        this.displayName = displayName;
        this.hue = hue;
    }

    public int getHue() {
        return hue;
    }

    @Override
    public String toString() {
        return displayName;
    }
}

package com.harrystyles.drystreaktracker;

import com.harrystyles.drystreaktracker.cosmetic.SmokeLootbeamColor;
import net.runelite.client.config.*;

@ConfigGroup("drystreaktracker")
public interface DryStreakTrackerConfig extends Config {

    /**
     * General group/settings
     */
    @ConfigSection(
            name = "General",
            description = "Configure Dry Streak Tracker chatbox settings",
            position = 0
    )
    String generalSection = "general";

    @ConfigItem(
            keyName = "trackPets",
            name = "Track pet drops",
            description = "Allow pet drops to count as tracked drops and reset dry streaks",
            position = 0,
            section = generalSection
    )


    default boolean trackPets() {
        return false;
    }

    @ConfigItem(
            keyName = "customNpcTracking",
            name = "Custom NPC tracking",
            description = "Adds a right-click option to NPCs for creating custom encounters. The NPC's drop table is loaded from the OSRS Wiki so you can choose which drops should end your dry streak.",
            position = 1,
            section = generalSection
    )
    default boolean customNpcTracking() {
        return false;
    }

    /**
     * Chatbox group/settings
     */
    @ConfigSection(
            name = "Chatbox",
            description = "Configure Dry Streak Tracker chatbox settings",
            position = 1
    )
    String chatboxSection = "chatbox";

    @ConfigItem(
            keyName = "showChatboxMessages",
            name = "Show Chatbox messages",
            description = "Show dry streak tracker messages in the chatbox",
            position = 0,
            section = chatboxSection
    )

    default boolean showChatboxMessages() {
        return true;
    }


    /**
     * Notification Group/Settings
     */
    @ConfigSection(
            name = "Notifications",
            description = "Configure Dry Streak Tracker pop-up notification settings",
            position = 2
    )
    String notificationSection = "notifications";




    /**
     * Cosmetic Effects group/settings
     */
    @ConfigSection(
            name = "Cosmetic Effects",
            description = "Configure cosmetic effects used by Dry Streak Tracker",
            position = 3
    )
    String cosmeticEffectsSection = "cosmeticEffects";

    @ConfigItem(
            keyName = "enableSmokeLootbeams",
            name = "Enable Smoke Lootbeams",
            description = "Show an animated customizable smoke effect over tracked ground drops",
            position = 0,
            section = cosmeticEffectsSection
    )
    default boolean enableSmokeLootbeams() {
        return false;
    }

    @ConfigItem(
            keyName = "smokeLootbeamColor",
            name = "Smoke color",
            description = "Choose the color used by Smoke Lootbeams",
            position = 1,
            section = cosmeticEffectsSection
    )
    default SmokeLootbeamColor smokeLootbeamColor() {
        return SmokeLootbeamColor.PURPLE;
    }




    @ConfigSection(
            name = "Discord Integration",
            description = "Discord integration settings",
            position = 4
    )
    String discordSection = "discord";

    @ConfigItem(
            keyName = "discordWebhookUrl",
            name = "Discord webhook URL",
            description = "Webhook used to upload tracked drops to Discord",
            position = 0,
            section = discordSection
    )
    default String discordWebhookUrl() {
        return "";
    }

    @Range(
            min = 0,
            max = Integer.MAX_VALUE
    )
    @ConfigItem(
            keyName = "discordMinimumGeValue",
            name = "Minimum GE value",
            description = "Minimum GE value required before a drop can be AUTOMATICALLY uploaded to Discord",
            position = 1,
            section = discordSection
    )
    default int discordMinimumGeValue() {
        return 10000000;
    }

    @ConfigItem(
            keyName = "discordAutomaticUploads",
            name = "Automatically upload drops",
            description = "Automatically send eligible tracked drops and a screenshot to the configured Discord webhook",
            position = 2,
            section = discordSection
    )
    default boolean discordAutomaticUploads() {
        return false;
    }

    @ConfigItem(
            keyName = "discordIncludeScreenshot",
            name = "Include screenshot for Auto-Upload",
            description = "Include a RuneLite screenshot with automatic Discord uploads",
            position = 3,
            section = discordSection
    )

    default boolean discordIncludeScreenshot() {
        return false;
    }

    @ConfigItem(
            keyName = "discordAlwaysUploadPets",
            name = "Always upload pets",
            description = "Always upload tracked pet drops regardless of the minimum GE value",
            position = 4,
            section = discordSection
    )
    default boolean discordAlwaysUploadPets() {
        return true;
    }




    /**
     * Debugging group/settings
     */
    @ConfigSection(
            name = "Debugging",
            description = "Configure Dry Streak Tracker debug settings",
            position = 5
    )
    String debuggingSection = "debugging";

    @ConfigItem(
            keyName = "showLootSourceDebug",
            name = "Show loot sources",
            description = "Show loot source names in the chatbox for reporting missing encounters.",
            position = 0,
            section = debuggingSection
    )
    default boolean showLootSourceDebug() {
        return false;
    }

}

package com.harrystyles.drystreaktracker.storage;

import com.harrystyles.drystreaktracker.encounter.tracking.PlayerTrackingData;

import com.google.gson.Gson;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;

import javax.inject.Inject;
import javax.inject.Singleton;

import lombok.extern.slf4j.Slf4j;

import net.runelite.client.config.ConfigManager;

/**
 * Handles persistent player tracking data.
 * <p>
 * Tracking data is stored separately for each RuneScape
 * character based on the logged-in player's name.
 *
 * @author Harry Styles
 */
@Slf4j
@Singleton
public class DryStreakStorage {
    private static final String CONFIG_GROUP = "drystreaktracker";

    private static final String DATA_KEY_PREFIX = "trackingData_";

    private final ConfigManager configManager;

    private final Gson gson;

    @Inject
    public DryStreakStorage(ConfigManager configManager, Gson gson) {
        this.configManager = configManager;
        this.gson = gson;
    }

    /**
     * Loads tracking data for a specific RuneScape account.
     *
     * @param playerName RuneScape character name.
     * @return Saved tracking data, or an empty data object
     * if no data exists.
     */
    public PlayerTrackingData load(String playerName) {
        if (playerName == null || playerName.trim().isEmpty()) {
            log.warn("Cannot load tracking data: player name is empty");

            return new PlayerTrackingData();
        }

        String dataKey = createDataKey(playerName);

        String json = configManager.getConfiguration(CONFIG_GROUP, dataKey);

        if (json == null || json.trim().isEmpty()) {
            log.debug("No saved tracking data found for account {}", playerName);

            return new PlayerTrackingData();
        }

        try {
            /**
             * Normal format:
             *
             * {
             *   "version": 1,
             *   "encounters": {}
             * }
             */
            if (json.trim().startsWith("{")) {
                PlayerTrackingData data = gson.fromJson(json, PlayerTrackingData.class);

                return data != null ? data : new PlayerTrackingData();
            }

            /**
             * Compatibility with old/double-encoded data.
             */
            String decoded = gson.fromJson(json, String.class);

            if (decoded != null && decoded.trim().startsWith("{")) {
                PlayerTrackingData data = gson.fromJson(decoded, PlayerTrackingData.class);

                return data != null ? data : new PlayerTrackingData();
            }

            log.warn("Saved tracking data for {} has an unexpected format", playerName
            );

            return new PlayerTrackingData();
        } catch (Exception e) {
            log.error("Failed to parse saved tracking data for account {}. " + "Starting with empty tracking data.", playerName, e);

            return new PlayerTrackingData();
        }
    }

    /**
     * Saves tracking data for a specific RuneScape account.
     *
     * @param playerName RuneScape character name.
     * @param data       Tracking data.
     */
    public void save(String playerName, PlayerTrackingData data) {
        if (playerName == null || playerName.trim().isEmpty()) {
            log.warn("Cannot save tracking data: player name is empty");

            return;
        }

        if (data == null) {
            return;
        }

        try {
            String json = gson.toJson(data);

            String dataKey = createDataKey(playerName);

            configManager.setConfiguration(CONFIG_GROUP, dataKey, json);

            log.debug("Saved tracking data for account {}", playerName);
        } catch (Exception e) {
            log.error("Failed to save tracking data for account {}", playerName, e);
        }
    }

    /**
     * Clears all saved tracking data for a specific
     * RuneScape account.
     *
     * @param playerName RuneScape character name.
     */
    public void clear(String playerName) {
        if (playerName == null || playerName.trim().isEmpty()) {
            return;
        }

        String dataKey = createDataKey(playerName);

        configManager.unsetConfiguration(CONFIG_GROUP, dataKey);

        log.info("Cleared saved tracking data for account {}", playerName);
    }

    /**
     * Creates the ConfigManager key for an account.
     * <p>
     * A SHA-256 hash is used instead of the raw player
     * name so ConfigManager never receives problematic
     * characters from a RuneScape username.
     */
    private String createDataKey(String playerName) {
        String normalizedName = playerName.trim().toLowerCase();

        return DATA_KEY_PREFIX + sha256(normalizedName);
    }

    /**
     * Creates a SHA-256 hash.
     */
    private String sha256(String value) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");

            byte[] hash = digest.digest(value.getBytes(StandardCharsets.UTF_8));

            StringBuilder result = new StringBuilder();

            for (byte b : hash) {
                result.append(String.format("%02x", b));
            }

            return result.toString();
        } catch (Exception e) {
            throw new IllegalStateException("Unable to generate account storage key", e);
        }
    }
}

package com.harrystyles.drystreaktracker.detection;

import com.harrystyles.drystreaktracker.DryStreakTrackerConfig;
import com.harrystyles.drystreaktracker.cosmetic.SmokeLootbeamManager;
import com.harrystyles.drystreaktracker.discord.DiscordWebhookService;
import com.harrystyles.drystreaktracker.discord.DropScreenshotService;
import com.harrystyles.drystreaktracker.encounter.EncounterDefinition;
import com.harrystyles.drystreaktracker.encounter.EncounterLootType;
import com.harrystyles.drystreaktracker.encounter.EncounterRegistry;
import com.harrystyles.drystreaktracker.encounter.EncounterStats;
