    private final SmokeLootbeamManager smokeLootbeamManager;

    /**
     * Pet tracking
     */
    private final PetAcquisitionTracker petAcquisitionTracker = new PetAcquisitionTracker();
    private EncounterDefinition pendingPetDryEncounter;
    private int pendingPetDryTick = -1;
    private int pendingPetDryStreak;
    private boolean pendingPetDryRecord;

    /**
     * NpcLootReceived events already processed during the current game tick.
     *
     * RuneLite normally follows NpcLootReceived with a LootReceived event for
     * the same NPC loot. These fingerprints allow LootReceived to act as a
     * fallback without counting normal NPC kills twice.
     */
    private final Map<String, Integer> processedNpcLootThisTick = new HashMap<>();
    private int processedNpcLootTick = -1;

    /**
     * Death lifecycle tracking for NPC-based GROUND_LOOT encounters.
     */
    private final GroundLootKillTracker groundLootKillTracker;

    @Inject
    public LootDetectionService(Client client, EncounterRegistry encounterRegistry, EncounterTrackerManager trackerManager,
        DryStreakTrackerConfig config, ItemManager itemManager,
        DryStreakSidebarPanel sidebarPanel, DiscordWebhookService discordWebhookService, DropScreenshotService dropScreenshotService,
        SmokeLootbeamManager smokeLootbeamManager, GroundLootKillTracker groundLootKillTracker) {
        this.client = client;
        this.encounterRegistry = encounterRegistry;
        this.trackerManager = trackerManager;
        this.config = config;
        this.itemManager = itemManager;
        this.sidebarPanel = sidebarPanel;
        this.discordWebhookService = discordWebhookService;
        this.dropScreenshotService = dropScreenshotService;
        this.smokeLootbeamManager = smokeLootbeamManager;
        this.groundLootKillTracker = groundLootKillTracker;
    }


    /**
     * Handles normal NPC death loot
     * Definition source:
     * <p>
     * encounters.json
     * <p>
     * Detection flow:
     * <p>
     * NPC dies
     * -> NpcLootReceived
     * -> NPC ID
     * -> EncounterRegistry
     * -> encounter completion
     */
    public void handleNpcLootReceived(NpcLootReceived event) {
        if (!canProcess()) {
            return;
        }

        if (event == null || event.getNpc() == null) {
            return;
        }

        NPC npc = event.getNpc();

        int npcId = npc.getId();

        Collection<ItemStack> items = event.getItems();

        log.debug("NpcLootReceived: npc={} id={} tick={} items={}", npc.getName(), npcId, client.getTickCount(), items == null ? 0 : items.size());

        if (items != null) {
            for (ItemStack item : items) {
                log.info("[DST DEBUG] NpcLootReceived item: id={} qty={}", item.getId(), item.getQuantity());
            }
        }

        EncounterDefinition encounter = encounterRegistry.getByNpcId(npcId);

        log.info("[DST DEBUG] Registry lookup by NPC ID {} -> {}",
                npcId,
                encounter == null ? "NO MATCH" : encounter.getEncounterId());

        /*
         * A custom NPC may have multiple visual variants with different
         * NPC IDs.
         *
         * Built-in encounters always win by exact NPC ID. Custom name +
         * combat level is only used when no registered NPC ID matched.
         */
        if (encounter == null) {
            encounter = trackerManager.getCustomEncounterByNpc(npc.getName(), npc.getCombatLevel());
        }

        if (encounter == null) {
            return;
        }

        if (encounter.getLootType() != EncounterLootType.GROUND_LOOT) {
            log.debug("Ignoring NpcLootReceived for {} because lootType={}", encounter.getEncounterId(), encounter.getLootType());

            return;
        }

        GroundLootKillTracker.PendingDeath pendingDeath = groundLootKillTracker.consumePendingDeath(encounter, npc);

        /*
         * If this exact death was already completed through the no-loot
         * fallback, this is late loot from the same NPC.
         */
        if (pendingDeath == null && groundLootKillTracker.wasDeathFinalized(encounter, npc)) {
            log.debug("Ignoring late NpcLootReceived for already finalized ground-loot NPC death {} ({})", npc.getName(), npc.getId());

            rememberNpcLootEvent(encounter, items);

            return;
        }

        boolean petMessageMatchedBeforeLoot = false;

        if (isPetTrackingEnabledForEncounter(encounter)) {
            petMessageMatchedBeforeLoot = petAcquisitionTracker.matchEncounterLootToPendingPetMessage(encounter, client.getTickCount());
        }

        String eventKey = pendingDeath != null
                ? pendingDeath.createEventKey()
                : createNpcKillEventKey(npc, items);

        rememberNpcLootEvent(encounter, items);

        processEncounterLoot(encounter, items, eventKey, petMessageMatchedBeforeLoot);

        /*
         * This applies to both official and custom GROUND_LOOT encounters.
         *
         * It also protects against RuneLite delivering NpcLootReceived
         * before ActorDeath.
         */
        groundLootKillTracker.finalizeDeath(encounter, npc, client.getTickCount());
    }


    /**
     * Handles RuneLite's generic LootReceived event.
     * Definition source:
     * loot-received-encounters.json
     *
     * This may include:
     * pickpocketing
     * object/chest rewards
     * reward containers
     * raid/event loot
     * other Loot Tracker sources
     */
    public void handleLootReceived(LootReceived event) {
        if (!canProcess()) {
            return;
        }

        if (event == null) {
            return;
        }

        if (event.getItems() == null || event.getItems().isEmpty()) {
            return;
        }

        String sourceName = event.getName();

        if (sourceName == null || sourceName.trim().isEmpty()) {
            log.debug("Ignoring LootReceived event with no source name");

            return;
        }

        log.debug("LootReceived: source={} type={} amount={} items={}", sourceName, event.getType(), event.getAmount(), event.getItems().size());

        /*
         * Normal loot-received encounters keep using the existing
         * source-name based path.
         */
        EncounterDefinition encounter = encounterRegistry.getByLootSourceName(sourceName);

        if (encounter != null && encounter.getLootType() == EncounterLootType.LOOT_RECEIVED) {
            boolean petMessageMatchedBeforeLoot = false;

            if (isPetTrackingEnabledForEncounter(encounter)) {
                petMessageMatchedBeforeLoot = petAcquisitionTracker.matchEncounterLootToPendingPetMessage(encounter, client.getTickCount());
            }

            String eventKey = createGenericLootEventKey(event);

            processEncounterLoot(encounter, event.getItems(), eventKey, petMessageMatchedBeforeLoot);

            return;
        }

        /*
         * RuneLite normally detects NPC encounters through
         * NpcLootReceived. However, some ground-item quantity changes
         * can reach LootReceived without producing NpcLootReceived.
         *
         * Use the generic NPC loot event as a fallback in that case.
         */
        if (event.getType() == LootRecordType.NPC) {
            EncounterDefinition groundLootEncounter = encounterRegistry.getGroundLootBySourceName(sourceName);

            if (groundLootEncounter != null) {
                /*
                 * A matching NpcLootReceived already processed this exact loot
                 * during this tick.
                 */
                if (consumeNpcLootEvent(groundLootEncounter, event.getItems())) {
                    log.debug("Ignoring paired LootReceived for {} because NpcLootReceived already processed it", groundLootEncounter.getEncounterId());

                    return;
                }

                /*
                 * LootReceived does not provide the NPC object, so pair it to
                 * the oldest pending death for this encounter.
                 */
                GroundLootKillTracker.PendingDeath pendingDeath = groundLootKillTracker.consumePendingDeath(groundLootEncounter);

                /*
                 * If there is no pending death and this encounter was just
                 * finalized, this may be a late duplicate fallback event.
                 */
                if (pendingDeath == null && groundLootKillTracker.wasEncounterRecentlyFinalized(groundLootEncounter)) {
                    log.debug("Ignoring late LootReceived fallback for already finalized ground-loot encounter {}", groundLootEncounter.getEncounterId());

                    return;
                }

                log.debug("Processing NPC LootReceived fallback for {}", groundLootEncounter.getEncounterId());

                boolean petMessageMatchedBeforeLoot = false;

                if (isPetTrackingEnabledForEncounter(groundLootEncounter)) {
                    petMessageMatchedBeforeLoot = petAcquisitionTracker.matchEncounterLootToPendingPetMessage(groundLootEncounter, client.getTickCount());
                }

                String eventKey = pendingDeath != null
                        ? pendingDeath.createEventKey()
                        : createNpcLootFallbackEventKey(groundLootEncounter, event);

                processEncounterLoot(groundLootEncounter, event.getItems(), eventKey, petMessageMatchedBeforeLoot);

                /*
                 * When a pending death was available we know exactly which
                 * NPC was completed and can retain its exact identity.
                 *
                 * Otherwise generic LootReceived gives us no NPC object.
                 */
                if (pendingDeath != null) {
                    groundLootKillTracker.finalizeDeath(pendingDeath, client.getTickCount());
                } else {
                    groundLootKillTracker.finalizeEncounter(groundLootEncounter, client.getTickCount());
                }

                return;
            }
        }

        if (config.showLootSourceDebug() && encounter == null) {
            sendLootSourceDebugMessage(sourceName);
        }

        log.debug("No encounter registered for LootReceived source '{}'", sourceName);
    }

    /**
     * Handles actual NPC deaths for custom encounters.
     *
     * Custom NPC tracking must not depend entirely on loot events because
     * some NPC kills legitimately produce no loot.
     *
     * The death itself is not recorded immediately. It is held briefly so
     * RuneLite has time to provide NpcLootReceived or LootReceived first.
     */
    public void handleActorDeath(ActorDeath event) {
        if (event != null && event.getActor() instanceof NPC) {
            NPC npc = (NPC) event.getActor();

            EncounterDefinition encounter = encounterRegistry.getByNpcId(npc.getId());

            log.info("[DST DEBUG] ActorDeath: npc='{}' id={} combat={} tick={} registryMatch={}",
                    npc.getName(),
                    npc.getId(),
                    npc.getCombatLevel(),
                    client.getTickCount(),
                    encounter == null ? "NO MATCH" : encounter.getEncounterId());
        }

        groundLootKillTracker.handleActorDeath(event);
    }

    /**
     * Marks a pending custom NPC death as having finished its
     * death animation and left the scene.
     *
     * The no-loot grace period begins here instead of ActorDeath
     * because many NPCs do not spawn their loot until several
     * ticks after ActorDeath fires.
     */
    public void handleNpcDespawned(NpcDespawned event) {
        if (event != null && event.getNpc() != null) {
            NPC npc = event.getNpc();

            EncounterDefinition encounter = encounterRegistry.getByNpcId(npc.getId());

            log.info("[DST DEBUG] NpcDespawned: npc='{}' id={} combat={} tick={} registryMatch={}",
                    npc.getName(),
                    npc.getId(),
                    npc.getCombatLevel(),
                    client.getTickCount(),
                    encounter == null ? "NO MATCH" : encounter.getEncounterId());
        }

        groundLootKillTracker.handleNpcDespawned(event);
    }

    public void handleInteractingChanged(InteractingChanged event) {
        groundLootKillTracker.handleInteractingChanged(event);
    }


    private boolean canProcess() {
        return trackerManager.isActive() && client.getGameState() == GameState.LOGGED_IN;
    }


    /**
     * Converts one RuneLite loot event into one encounter
     * completion.
     *
     * Both NpcLootReceived and LootReceived eventually come
     * through this method.
     */
    private void processEncounterLoot(EncounterDefinition encounter, Collection<ItemStack> items, String eventKey, boolean petMessageMatchedBeforeLoot) {
        if (encounter == null) {
            return;
        }
        log.info("[DST DEBUG] processEncounterLoot: encounter='{}' eventKey='{}' tick={} itemCount={} petMatched={}",
                encounter.getEncounterId(),
                eventKey,
                client.getTickCount(),
                items == null ? 0 : items.size(),
                petMessageMatchedBeforeLoot);
        /*
         * Only normal tracked items are searched here.
         *
         * Pets are detected separately through the RuneScape
         * pet acquisition game message.
         */
        Map<Integer, Integer> qualifyingDrops = findQualifyingDrops(encounter, items);

        log.info("[DST DEBUG] Qualifying tracked drops for '{}': {}",
                encounter.getEncounterId(),
                qualifyingDrops);

        if (items != null) {
            for (ItemStack item : items) {
                log.info("[DST DEBUG] Item check for '{}': itemId={} qty={} configured={} enabled={}",
                        encounter.getEncounterId(),
                        item.getId(),
                        item.getQuantity(),
                        encounter.isTrackedDrop(item.getId()),
                        trackerManager.isDropEnabled(encounter.getEncounterId(), item.getId()));
            }
        }

        Integer firstDropItemId = null;
        int firstDropQuantity = 0;

        if (!qualifyingDrops.isEmpty()) {
            Map.Entry<Integer, Integer> firstDrop = qualifyingDrops.entrySet().iterator().next();

            firstDropItemId = firstDrop.getKey();
            firstDropQuantity = firstDrop.getValue();
        }

        /*
         * The encounter itself is recorded exactly once.
         *
         * The first tracked item, if present, is responsible for ending
         * the dry streak. Any additional tracked items are attached to
         * this same kill below.
         */
        log.info("[DST DEBUG] Calling recordKill: encounter='{}' eventKey='{}' trackedDrop={} quantity={}",
                encounter.getEncounterId(),
                eventKey,
                firstDropItemId,
                firstDropQuantity);

        boolean recorded = trackerManager.recordKill(encounter.getEncounterId(), eventKey, firstDropItemId, firstDropQuantity);

        log.info("[DST DEBUG] recordKill result for '{}': {}",
                encounter.getEncounterId(),
                recorded);

        if (!recorded) {
            log.warn("[DST DEBUG] KILL WAS NOT RECORDED for encounter='{}' eventKey='{}'",
                    encounter.getEncounterId(),
                    eventKey);

            return;
        }

        /*
         * Smoke Lootbeams only apply to normal ground loot which was
         * actually received from a successfully recorded encounter.
         *
         * ItemSpawned itself is deliberately not trusted to determine
         * ownership because it also fires for static world spawns and
         * other unrelated ground items.
         */
        if (encounter.getLootType() == EncounterLootType.GROUND_LOOT && !qualifyingDrops.isEmpty()) {
            smokeLootbeamManager.markEarnedDrops(qualifyingDrops.keySet());
        }

        /*
         * Process every tracked item received from this encounter.
         */
        boolean firstDrop = true;

        for (Map.Entry<Integer, Integer> entry : qualifyingDrops.entrySet()) {
            int itemId = entry.getKey();
            int quantity = entry.getValue();

            if (firstDrop) {
                firstDrop = false;

                processRecordedDrop(encounter, itemId, quantity, false);

                continue;
            }

            if (trackerManager.recordAdditionalDropForLastKill(encounter.getEncounterId(), itemId, quantity)) {
                processRecordedDrop(encounter, itemId, quantity, false);
            }
        }

        /*
         * The pet message arrived before the loot event.
         *
         * The kill has already been recorded above, so attach
         * the pet to that existing kill instead of creating a
         * second encounter completion.
         */
        if (petMessageMatchedBeforeLoot) {
            Integer petItemId = getPetItemId(encounter);

            if (petItemId != null && trackerManager.recordPetForLastKill(encounter.getEncounterId(), petItemId)) {
                clearPendingPetDryResult();

                processRecordedDrop(encounter, petItemId, 1, true);
            }
        }

        EncounterStats stats = trackerManager.getStats(encounter.getEncounterId());

        if (stats != null) {
            Map<Integer, ItemDisplayData> displayData = resolveEncounterItemDisplayData(stats);

            sidebarPanel.updateItemDisplayData(displayData);
        }

        /*
         * It was genuinely a dry kill only when neither a
         * normal tracked drop nor a pet was received.
         */
        if (qualifyingDrops.isEmpty() && !petMessageMatchedBeforeLoot) {
            /*
             * Pet-eligible encounters wait briefly before announcing
             * a dry kill because the pet acquisition message may
             * arrive shortly after the loot event.
             */
            if (isPetTrackingEnabledForEncounter(encounter)) {
                queuePendingPetDryResult(encounter, stats);

                return;
            }

            if (stats != null && stats.isNewDryRecordThisKill()) {

                if (config.showChatboxMessages()) {
                    sendDryRecordChatboxMessage(encounter, stats);
                }

                return;
            }

            if (config.showChatboxMessages()) {
                sendDryKillChatboxMessage(encounter);
            }

            return;
        }

        if (stats != null && stats.isNewDryRecordThisKill()) {

            if (config.showChatboxMessages()) {
                sendDryRecordChatboxMessage(encounter, stats);
            }
        }
    }

    /**
     * Finishes custom NPC deaths which never produced a loot event.
     *
     * ActorDeath only tells us that the NPC has started dying.
     * Some NPCs have several ticks of death animation before their
     * ground loot is actually created.
     *
     * Therefore the normal no-loot timer begins at NpcDespawned,
     * not ActorDeath.
     */
    public void processPendingGroundLootDeaths() {
        if (!canProcess()) {
            return;
        }

        int currentTick = client.getTickCount();

        for (GroundLootKillTracker.PendingDeath pendingDeath : groundLootKillTracker.pollNoLootDeaths()) {
            recordNoLootGroundLootDeath(pendingDeath, currentTick);
        }
    }

    private void recordNoLootGroundLootDeath(GroundLootKillTracker.PendingDeath pendingDeath, int currentTick) {
        if (pendingDeath == null) {
            return;
        }

        EncounterDefinition encounter = encounterRegistry.getById(pendingDeath.getEncounterId());

        if (encounter == null
                || encounter.getLootType() != EncounterLootType.GROUND_LOOT) {
            return;
        }

        /*
         * Empty loot is intentional.
         *
         * processEncounterLoot() will record one kill with no qualifying
         * drop, which increments the encounter's dry streak normally.
         */
        processEncounterLoot(encounter, Collections.emptyList(), pendingDeath.createEventKey(), false);

        groundLootKillTracker.finalizeDeath(pendingDeath, currentTick);

        log.debug(
                "Recorded no-loot ground-loot NPC death for {} deathTick={} despawnTick={} finalizedTick={}",
                encounter.getEncounterId(),
                pendingDeath.getDeathTick(),
                pendingDeath.getDespawnTick(),
                currentTick
        );
    }

    /**
     * Releases a delayed dry result once the pet acquisition
     * matching window has expired.
     */
    public void processPendingPetDryResult() {
        if (!canProcess()) {
            return;
        }

        if (pendingPetDryEncounter == null || pendingPetDryTick < 0) {
            return;
        }

        int ticksElapsed = client.getTickCount() - pendingPetDryTick;

        if (ticksElapsed <= PetAcquisitionTracker.MATCH_WINDOW_TICKS) {
            return;
        }

        EncounterDefinition encounter = pendingPetDryEncounter;

        int dryStreak = pendingPetDryStreak;

        boolean newDryRecord = pendingPetDryRecord;

        /*
         * Clear first so the result cannot accidentally be sent
         * twice.
         */
        clearPendingPetDryResult();

        if (newDryRecord) {
            if (config.showChatboxMessages()) {
                sendDryRecordChatboxMessage(encounter, dryStreak);
            }

            return;
        }

        if (config.showChatboxMessages()) {
            sendDryKillChatboxMessage(encounter, dryStreak);
        }
    }


    /**
     * Holds a dry result temporarily while waiting to see
     * whether a pet aquisition message belongs to the kill
     */
    private void queuePendingPetDryResult(EncounterDefinition encounter, EncounterStats stats) {
        if (encounter == null || stats == null) {
            return;
        }

        pendingPetDryEncounter = encounter;

        pendingPetDryTick = client.getTickCount();

        pendingPetDryStreak = stats.getCurrentDryStreak();

        pendingPetDryRecord = stats.isNewDryRecordThisKill();
    }

    /**
     * Clears a dry result that was waiting for the pet
     * acquisition matching window
     */
    private void clearPendingPetDryResult() {
        pendingPetDryEncounter = null;

        pendingPetDryTick = -1;

        pendingPetDryStreak = 0;

        pendingPetDryRecord = false;
    }

    /**
     * Returns the configured pet item id for an encounter
     */
    private Integer getPetItemId(EncounterDefinition encounter) {
        if (encounter == null || encounter.getPetDropIds() == null || encounter.getPetDropIds().isEmpty()) {
            return null;
        }

        return encounter.getPetDropIds().iterator().next();
    }

    /**
     * Returns whether pet detection should be active for this
     * encounter
     */
    private boolean isPetTrackingEnabledForEncounter(EncounterDefinition encounter) {
        return config.trackPets() && getPetItemId(encounter) != null;
    }

    /**
     * Handles recent-drop history and Discord uploads after a tracked item has been recorded.
     *
     * This method does not modify encounter kill totals.
     */
    private void processRecordedDrop(EncounterDefinition encounter, int itemId, int quantity, boolean pet) {
        long gePrice = itemManager.getItemPrice(itemId);

        long totalGeValue = gePrice * quantity;

        trackerManager.recordRecentDrop(encounter.getEncounterId(), itemId, quantity, totalGeValue);

        Map<Integer, ItemDisplayData> displayData = new HashMap<>();

        String itemName = getItemName(itemId);

        Image itemImage = itemManager.getImage(itemId);

        displayData.put(itemId, new ItemDisplayData(itemName, itemImage));

        sidebarPanel.updateItemDisplayData(displayData);

        if (config.discordAutomaticUploads()) {
            RecentDrop recentDrop = trackerManager.getRecentDrops().isEmpty()
                    ? null
                    : trackerManager.getRecentDrops().get(0);

            if (recentDrop != null && discordWebhookService.canAutomaticallyUpload(recentDrop, pet)) {

                if (config.discordIncludeScreenshot()) {
                    dropScreenshotService.captureScreenshot(screenshot -> discordWebhookService.uploadDrop(recentDrop, itemName, screenshot));
                } else {
                    discordWebhookService.uploadDrop(recentDrop, itemName);
                }
            }
        }

        handleRecordedDrop(encounter, itemId, quantity, pet);
    }

    /**
     * Finds all tracked drops contained in one loot event.
     * <p>
     * Multiple tracked uniques may legitimately be received from
     * the same encounter completion.
     */
    private Map<Integer, Integer> findQualifyingDrops(EncounterDefinition encounter, Collection<ItemStack> items) {
        Map<Integer, Integer> qualifyingDrops = new LinkedHashMap<>();

        if (encounter == null || items == null || items.isEmpty()) {
            return qualifyingDrops;
        }

        for (ItemStack item : items) {
            if (item == null || !trackerManager.isDropEnabled(encounter.getEncounterId(), item.getId())) {
                continue;
            }

            qualifyingDrops.merge(item.getId(), item.getQuantity(), Integer::sum);
        }

        return qualifyingDrops;
    }


    /**
     * Displays chat information for a
     * successfully recorded tracked drop.
     */
    private void handleRecordedDrop(EncounterDefinition encounter, int itemId, int quantity, boolean pet) {
        String itemName = getItemName(itemId);

        EncounterStats stats = trackerManager.getStats(encounter.getEncounterId());

        if (config.showChatboxMessages()) {
            sendDropChatboxMessage(encounter, itemName, quantity, pet, stats);
        }
    }

    /**
     * Handles RuneScape game messages used to detect pet
     * acquisitions.
     */
    public void handlePetAcquisitionMessage(ChatMessage event) {
        if (!canProcess()) {
            return;
        }

        if (!config.trackPets()) {
            return;
        }

        if (event == null || event.getType() != ChatMessageType.GAMEMESSAGE) {
            return;
        }

        String message = Text.removeTags(event.getMessage());

        if (!petAcquisitionTracker.isPetAcquisitionMessage(message)) {
            return;
        }

        EncounterDefinition encounter = petAcquisitionTracker.matchPetMessageToRecentEncounter(client.getTickCount());

        /*
         * Null means the pet message arrived before the loot
         * event. The message is being held temporarily and will
         * be processed when the encounter loot arrives.
         */
        if (encounter == null) {
            return;
        }

        Integer petItemId = getPetItemId(encounter);

        if (petItemId == null) {
            return;
        }

        /*
         * Loot arrived first, so the encounter kill has already
         * been recorded.
         */
        boolean recorded = trackerManager.recordPetForLastKill(encounter.getEncounterId(), petItemId);

        if (!recorded) {
            return;
        }

        /*
         * This kill was waiting to be announced as dry, but the
         * pet message confirms that it was actually a pet kill.
         */
        clearPendingPetDryResult();

        processRecordedDrop(encounter, petItemId, 1, true);

        EncounterStats stats = trackerManager.getStats(encounter.getEncounterId());

        if (stats != null) {
            Map<Integer, ItemDisplayData> displayData = resolveEncounterItemDisplayData(stats);

            sidebarPanel.updateItemDisplayData(displayData);
        }
    }

    private void rememberNpcLootEvent(EncounterDefinition encounter, Collection<ItemStack> items) {
        int currentTick = client.getTickCount();

        if (processedNpcLootTick != currentTick) {
            processedNpcLootThisTick.clear();
            processedNpcLootTick = currentTick;
        }

        String matchKey = createNpcLootMatchKey(encounter, items);

        processedNpcLootThisTick.merge(matchKey, 1, Integer::sum);
    }


    private boolean consumeNpcLootEvent(EncounterDefinition encounter, Collection<ItemStack> items) {
        int currentTick = client.getTickCount();

        if (processedNpcLootTick != currentTick) {
            processedNpcLootThisTick.clear();
            processedNpcLootTick = currentTick;

            return false;
        }

        String matchKey = createNpcLootMatchKey(encounter, items);

        Integer amount = processedNpcLootThisTick.get(matchKey);

        if (amount == null || amount <= 0) {
            return false;
        }

        if (amount == 1) {
            processedNpcLootThisTick.remove(matchKey);
        } else {
            processedNpcLootThisTick.put(matchKey, amount - 1);
        }

        return true;
    }


    private String createNpcLootMatchKey(EncounterDefinition encounter, Collection<ItemStack> items) {
        StringBuilder key = new StringBuilder();

        key.append(encounter.getEncounterId());

        Map<Integer, Integer> quantities = new TreeMap<>();

        if (items != null) {
            for (ItemStack item : items) {
                if (item == null) {
                    continue;
                }

                quantities.merge(item.getId(), item.getQuantity(), Integer::sum);
            }
        }

        for (Map.Entry<Integer, Integer> entry : quantities.entrySet()) {
            key.append('|');
            key.append(entry.getKey());
            key.append('x');
            key.append(entry.getValue());
        }

        return key.toString();
    }


    private String createNpcLootFallbackEventKey(EncounterDefinition encounter, LootReceived event) {
        StringBuilder key = new StringBuilder();

        key.append("npc-fallback|");
        key.append(client.getTickCount());
        key.append('|');
        key.append(encounter.getEncounterId());

        appendItemsToKey(key, event.getItems());

        return key.toString();
    }


    /**
     * Generates a fingerprint for NpcLootReceived.
     * <p>
     * This prevents the exact same kill event from being
     * recorded more than once.
     */
    private String createNpcKillEventKey(NPC npc, Collection<ItemStack> items) {
        StringBuilder key = new StringBuilder();

        key.append("npc|");

        key.append(client.getTickCount());

        key.append('|');

        key.append(npc.getId());

        key.append('|');

        key.append(npc.getIndex());

        appendItemsToKey(key, items);

        return key.toString();
    }


    /**
     * Generates a fingerprint for LootReceived.
     */
    private String createGenericLootEventKey(LootReceived event) {
        StringBuilder key = new StringBuilder();

        key.append("loot|");

        key.append(client.getTickCount());

        key.append('|');

        if (event.getType() != null) {
            key.append(event.getType().name());
        }

        key.append('|');

        if (event.getName() != null) {
            key.append(event.getName());
        }

        key.append('|');

        key.append(event.getAmount());

        appendItemsToKey(key, event.getItems()
        );

        return key.toString();
    }


    private void appendItemsToKey(StringBuilder key, Collection<ItemStack> items) {
        if (items == null) {
            return;
        }

        for (ItemStack item : items) {
            if (item == null) {
                continue;
            }

            key.append('|');

            key.append(item.getId());

            key.append('x');

            key.append(item.getQuantity());
        }
    }


    private Map<Integer, ItemDisplayData> resolveEncounterItemDisplayData(EncounterStats stats) {
        Map<Integer, ItemDisplayData> result = new HashMap<>();

        if (stats == null || stats.getReceivedDrops() == null || stats.getReceivedDrops().isEmpty()) {
            return result;
        }

        for (Integer itemId : stats.getReceivedDrops().keySet()) {
            if (itemId == null) {
                continue;
            }

            try {
                String itemName = getItemName(itemId);

                Image itemImage = itemManager.getImage(itemId);

                /**
                 * Store the item name even if the sprite has not
                 * finished loading yet.
                 *
                 * DropItemPanel handles a null image asynchronously.
                 */
                result.put(itemId, new ItemDisplayData(itemName, itemImage));
            } catch (Exception e) {
                log.debug("Unable to resolve item {}", itemId, e);
            }
        }

        return result;
    }


    private String getItemName(int itemId) {
        ItemComposition item = itemManager.getItemComposition(itemId);

        if (item != null && item.getName() != null && !item.getName().isEmpty()) {
            return item.getName();
        }

        return "Item " + itemId;
    }

    private void sendDryRecordChatboxMessage(EncounterDefinition encounter, int recordStreak) {
        if (encounter == null) {
            return;
        }

        String message = "[<col=FF0000>Dry Streak</col>] "
                + "[<col=FFFF00>"
                + encounter.getDisplayName()
                + "</col>]: "
                + "<col=800080>New dry streak record! "
                + recordStreak
                + " kc dry"
                + "</col>";

        client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
    }

    /**
     * Sends a chatbox message when the player surpasses
     * their previous longest dry streak.
     */
    private void sendDryRecordChatboxMessage(EncounterDefinition encounter, EncounterStats stats) {
        if (encounter == null || stats == null) {
            return;
        }

        int recordStreak = stats.getCurrentDryStreak() > 0
                ? stats.getCurrentDryStreak()
                : stats.getLastCompletedDryStreak();

        sendDryRecordChatboxMessage(encounter, recordStreak);
    }

    private void sendDropChatboxMessage(EncounterDefinition encounter, String itemName, int quantity, boolean pet, EncounterStats stats) {
        String dropType = pet ? "Pet" : "Drop";

        String message =
                "[<col=FF0000>Dry Streak</col>] "
                        + "[<col=FFFF00>"
                        + encounter.getDisplayName()
                        + "</col>]: "
                        + dropType
                        + " received: <col=800080>"
                        + itemName
                        + "</col> x"
                        + quantity;

        if (stats != null && stats.getLastCompletedDryStreak() > 0) {
            message += ". Dry streak ended at " + stats.getLastCompletedDryStreak() + " KC.";
        }

        message += " Dry streak reset.</col>";

        client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
    }

    private void sendDryKillChatboxMessage(EncounterDefinition encounter, int dryStreak) {
        if (encounter == null) {
            return;
        }

        String message =
                "[<col=FF0000>Dry Streak</col>] "
                        + "[<col=FFFF00>"
                        + encounter.getDisplayName()
                        + "</col>]: <col=800080>"
                        + dryStreak
                        + "</col> kc since last unique";

        client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
    }

    private void sendDryKillChatboxMessage(EncounterDefinition encounter) {
        EncounterStats stats = trackerManager.getStats(encounter.getEncounterId());

        if (stats == null) {
            return;
        }

        sendDryKillChatboxMessage(encounter, stats.getCurrentDryStreak());
    }


    public void clearProcessedLootEvents() {
        petAcquisitionTracker.clearPetAcquisitionState();

        clearPendingPetDryResult();

        processedNpcLootThisTick.clear();
        processedNpcLootTick = -1;

        groundLootKillTracker.clear();

        trackerManager.clearProcessedKillEvents();
    }

    /**
     * Displays internal LootReceived source name
     * for debugging and reporting missing encounters.
     */
    private void sendLootSourceDebugMessage(String sourceName) {
        if (sourceName == null || sourceName.trim().isEmpty()) {
            return;
        }

        String message =
                "[<col=FF0000>Dry Streak Debug</col>] "
                        + "Untracked loot source: "
                        + "<col=FFFF00>"
                        + sourceName
                        + "</col>"
                        + " <col=FFFFFF>- Please report this loot source on our Discord if you would like it added.</col>";

        client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
    }

}

package com.harrystyles.drystreaktracker.detection;

import com.harrystyles.drystreaktracker.encounter.EncounterDefinition;

/**
 * Associates RuneScape pet acquisition messages with
 * recently completed encounters.
 *
 * Pets are announced through game messages rather than
 * appearing as normal loot items.
 *
 * The pet message may arrive shortly before or after the
 * encounter loot event, so both event orders are supported.
 */
public class PetAcquisitionTracker {
    static final int MATCH_WINDOW_TICKS = 10;

    private static final int NO_TICK = Integer.MIN_VALUE / 2;

    private int pendingPetMessageTick = NO_TICK;

    private int recentEncounterTick = NO_TICK;

    private EncounterDefinition recentEncounter;

    /**
     * Checks whether a game message is one of RuneScape's
     * pet acquisition messages.
     */
    public boolean isPetAcquisitionMessage(String message) {
        if (message == null) {
            return false;
        }

        return message.startsWith("You have a funny feeling like you")
                || message.startsWith("You feel something weird sneaking");
    }

    /**
     * Records a recently completed encounter and checks whether
     * a pending pet acquisition message belongs to it
     *
     * @return true if a pet acquisition message arrived shortly
     * before this encounter's loot event
     */
    public boolean matchEncounterLootToPendingPetMessage(EncounterDefinition encounter, int tick) {
        if (encounter == null) {
            return false;
        }

        recentEncounter = encounter;
        recentEncounterTick = tick;

        if (isWithinWindow(tick, pendingPetMessageTick)) {
            pendingPetMessageTick = NO_TICK;

            clearRecentEncounter();

            return true;
        }

        return false;
    }

    /**
     * Called when RuneScape sends a pet acquisition message.
     *
     * @return the recently completed encounter if one can
     * immediately be matched, otherwise null
     */
    public EncounterDefinition matchPetMessageToRecentEncounter(int tick) {
        if (recentEncounter != null && isWithinWindow(tick, recentEncounterTick)) {
            EncounterDefinition encounter = recentEncounter;

            clearRecentEncounter();

            pendingPetMessageTick = NO_TICK;

            return encounter;
        }

        /*
         * The pet message may have arrived before the loot
         * event. Hold it temporarily until loot arrives.
         */
        pendingPetMessageTick = tick;

        /*
         * Do not keep an old encounter around once it has
         * fallen outside the matching window.
         */
        if (recentEncounter != null && !isWithinWindow(tick, recentEncounterTick)) {
            clearRecentEncounter();
        }

        return null;
    }

    /**
     * Clears transient pet detection state.
     */
    public void clearPetAcquisitionState() {
        pendingPetMessageTick = NO_TICK;

        clearRecentEncounter();
    }

    private boolean isWithinWindow(int currentTick, int previousTick) {
        if (previousTick == NO_TICK) {
            return false;
        }

        int difference = currentTick - previousTick;

        return difference >= 0 && difference <= MATCH_WINDOW_TICKS;
    }

    private void clearRecentEncounter() {
        recentEncounter = null;
        recentEncounterTick = NO_TICK;
    }
}

package com.harrystyles.drystreaktracker.detection;

import com.harrystyles.drystreaktracker.encounter.EncounterDefinition;
import com.harrystyles.drystreaktracker.encounter.EncounterLootType;
import com.harrystyles.drystreaktracker.encounter.EncounterRegistry;
import com.harrystyles.drystreaktracker.encounter.tracking.EncounterTrackerManager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;

import javax.inject.Inject;
import javax.inject.Singleton;

import lombok.extern.slf4j.Slf4j;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.InteractingChanged;
import net.runelite.api.events.NpcDespawned;

/**
 * Tracks the death lifecycle of NPC-based GROUND_LOOT encounters.
 *
 * Ground-loot encounters cannot rely entirely on loot events because
 * some NPC kills legitimately produce no ground loot.
 *
 * Lifecycle:
 *
 * local interaction
 * -> ActorDeath
 * -> pending death
 * -> NpcDespawned
 * -> loot event OR no-loot timeout
 *
 * LootDetectionService remains responsible for deciding whether the
 * resulting loot contains a tracked drop.
 */
@Slf4j
@Singleton
public class GroundLootKillTracker {
    /*
     * Keeps a player's NPC interaction around after they switch targets.
     *
     * This is required for fast ranged/projectile combat where the player
     * may already be attacking another NPC when the previous target dies.
     */
    private static final int INTERACTION_RETENTION_TICKS = 10;

    /*
     * Once the NPC disappears, give RuneLite a short period to deliver
     * NpcLootReceived/LootReceived before treating the kill as no-loot.
     */
    private static final int DESPAWN_LOOT_WAIT_TICKS = 2;

    private static final int YAMA_NPC_ID = 14176;
    private static final int YAMA_DESPAWN_LOOT_WAIT_TICKS = 4;

    /*
     * Emergency fallback only.
     *
     * NpcDespawned should normally arrive after ActorDeath. This prevents
     * an unusual missed despawn event from leaving a pending death forever.
     */
    private static final int DEATH_FALLBACK_TICKS = 20;

    /*
     * Completed deaths are remembered briefly so reversed or late
     * RuneLite events cannot count the same NPC twice.
     */
    private static final int FINALIZED_RETENTION_TICKS = 7;

    private final Client client;
    private final EncounterRegistry encounterRegistry;
    private final EncounterTrackerManager trackerManager;

    private final List<PendingDeath> pendingDeaths = new ArrayList<>();
    private final List<FinalizedDeath> finalizedDeaths = new ArrayList<>();
    private final Map<Long, Integer> recentInteractions = new HashMap<>();

    @Inject
    public GroundLootKillTracker(Client client, EncounterRegistry encounterRegistry, EncounterTrackerManager trackerManager) {
        this.client = client;
        this.encounterRegistry = encounterRegistry;
        this.trackerManager = trackerManager;
    }

    /**
     * Remembers NPCs targeted by the local player.
     *
     * NPC id + index is stored separately for every target so rapid
     * multi-target/projectile combat does not overwrite an earlier target.
     */
    public void handleInteractingChanged(InteractingChanged event) {
        if (!canProcess() || event == null || client.getLocalPlayer() == null) {
            return;
        }

        if (event.getSource() != client.getLocalPlayer()
                || !(event.getTarget() instanceof NPC)) {
            return;
        }

        NPC npc = (NPC) event.getTarget();

        EncounterDefinition encounter = getGroundLootEncounter(npc);

        if (encounter == null) {
            return;
        }

        /*
         * NPC indices are reused when NPCs respawn.
         *
         * Interacting with a living NPC proves that this id/index now
         * represents a new NPC incarnation. Remove a finalized marker
         * left by the previous NPC which occupied the same slot.
         */
        removeFinalizedDeath(encounter.getEncounterId(), npc.getId(), npc.getIndex());

        recentInteractions.put(createNpcKey(npc.getId(), npc.getIndex()), client.getTickCount());

        log.debug(
                "Remembered ground-loot NPC interaction: encounter={} npc={} id={} index={} tick={}",
                encounter.getEncounterId(),
                npc.getName(),
                npc.getId(),
                npc.getIndex(),
                client.getTickCount()
        );
    }

    /**
     * Creates a pending death for a ground-loot encounter.
     *
     * Nothing is recorded yet because the NPC may still produce loot.
     */
    public void handleActorDeath(ActorDeath event) {
        if (!canProcess()
                || event == null
                || !(event.getActor() instanceof NPC)) {
            return;
        }

        NPC npc = (NPC) event.getActor();

        EncounterDefinition encounter = getGroundLootEncounter(npc);

        if (encounter == null) {
            return;
        }

        /*
         * RuneLite can occasionally provide loot before ActorDeath.
         *
         * If this exact NPC death was already completed from loot,
         * do not create a second pending kill.
         */
        if (wasDeathFinalized(encounter, npc)) {
            log.debug(
                    "Ignoring ActorDeath for recently finalized ground-loot NPC: encounter={} npc={} id={} index={} tick={}",
                    encounter.getEncounterId(),
                    npc.getName(),
                    npc.getId(),
                    npc.getIndex(),
                    client.getTickCount()
            );

            return;
        }

        /*
         * ActorDeath is global. It also fires for NPCs killed by other
         * players, so no-loot tracking requires evidence that the local
         * player was fighting this exact NPC.
         */
        if (!wasLocalPlayerFightingNpc(npc)) {
            return;
        }

        recentInteractions.remove(createNpcKey(npc.getId(), npc.getIndex()));

        for (PendingDeath pendingDeath : pendingDeaths) {
            if (pendingDeath == null) {
                continue;
            }

            if (pendingDeath.npcId == npc.getId()
                    && pendingDeath.npcIndex == npc.getIndex()) {
                return;
            }
        }

        pendingDeaths.add(new PendingDeath(
                encounter.getEncounterId(),
                npc.getId(),
                npc.getIndex(),
                client.getTickCount()
        ));

        log.debug(
                "Pending ground-loot NPC death: encounter={} npc={} id={} index={} tick={}",
                encounter.getEncounterId(),
                npc.getName(),
                npc.getId(),
                npc.getIndex(),
                client.getTickCount()
        );
    }

    /**
     * Marks the end of a pending NPC's death animation.
     *
     * The normal no-loot grace period begins here rather than ActorDeath
     * because different NPCs have different death-animation lengths.
     */
    public void handleNpcDespawned(NpcDespawned event) {
        if (!canProcess() || event == null || event.getNpc() == null) {
            return;
        }

        NPC npc = event.getNpc();

        for (PendingDeath pendingDeath : pendingDeaths) {
            if (pendingDeath == null
                    || pendingDeath.npcId != npc.getId()
                    || pendingDeath.npcIndex != npc.getIndex()) {
                continue;
            }

            pendingDeath.despawnTick = client.getTickCount();

            log.debug(
                    "Pending ground-loot NPC death despawned: encounter={} npc={} id={} index={} deathTick={} despawnTick={}",
                    pendingDeath.encounterId,
                    npc.getName(),
                    npc.getId(),
                    npc.getIndex(),
                    pendingDeath.deathTick,
                    pendingDeath.despawnTick
            );

            return;
        }
    }


    /**
     * Consumes the exact pending death belonging to NpcLootReceived.
     */
    public PendingDeath consumePendingDeath(EncounterDefinition encounter, NPC npc) {
        if (encounter == null || npc == null) {
            return null;
        }

        Iterator<PendingDeath> iterator = pendingDeaths.iterator();

        while (iterator.hasNext()) {
            PendingDeath pendingDeath = iterator.next();

            if (pendingDeath == null) {
                iterator.remove();
                continue;
            }

            if (!encounter.getEncounterId().equals(pendingDeath.encounterId)
                    || pendingDeath.npcId != npc.getId()
                    || pendingDeath.npcIndex != npc.getIndex()) {
                continue;
            }

            iterator.remove();

            return pendingDeath;
        }

        return null;
    }

    /**
     * Generic LootReceived does not provide an NPC object.
     *
     * When it is being used as the NPC-loot fallback, consume the
     * oldest pending death belonging to this encounter.
     */
    public PendingDeath consumePendingDeath(EncounterDefinition encounter) {
        if (encounter == null) {
            return null;
        }

        PendingDeath oldestMatch = null;

        for (PendingDeath pendingDeath : pendingDeaths) {
            if (pendingDeath == null
                    || !encounter.getEncounterId().equals(pendingDeath.encounterId)) {
                continue;
            }

            if (oldestMatch == null || pendingDeath.deathTick < oldestMatch.deathTick) {
                oldestMatch = pendingDeath;
            }
        }

        if (oldestMatch != null) {
            pendingDeaths.remove(oldestMatch);
        }

        return oldestMatch;
    }

    /**
     * Returns deaths which have reached the confirmed no-loot state.
     *
     * LootDetectionService records the actual dry kill so all existing
     * encounter stats, notifications and saving still use one code path.
     */
    public List<PendingDeath> pollNoLootDeaths() {
        List<PendingDeath> noLootDeaths = new ArrayList<>();

        if (!canProcess()) {
            return noLootDeaths;
        }

        int currentTick = client.getTickCount();

        Iterator<PendingDeath> iterator = pendingDeaths.iterator();

        while (iterator.hasNext()) {
            PendingDeath pendingDeath = iterator.next();

            if (pendingDeath == null) {
                iterator.remove();
                continue;
            }

            /*
             * Normal path.
             *
             * Once the NPC has disappeared, wait briefly for its loot.
             */
            if (pendingDeath.despawnTick >= 0) {
                int ticksSinceDespawn = currentTick - pendingDeath.despawnTick;

                int lootWaitTicks = pendingDeath.npcId == YAMA_NPC_ID
                        ? YAMA_DESPAWN_LOOT_WAIT_TICKS
                        : DESPAWN_LOOT_WAIT_TICKS;

                if (ticksSinceDespawn <= lootWaitTicks) {
                    continue;
                }

                iterator.remove();
                noLootDeaths.add(pendingDeath);

                continue;
            }

            /*
             * Emergency fallback only.
             */
            int ticksSinceDeath = currentTick - pendingDeath.deathTick;

            if (ticksSinceDeath <= DEATH_FALLBACK_TICKS) {
                continue;
            }

            iterator.remove();

            log.debug(
                    "Ground-loot NPC death {} never received NpcDespawned after {} ticks; using fallback",
                    pendingDeath.encounterId,
                    ticksSinceDeath
            );

            noLootDeaths.add(pendingDeath);
        }

        cleanupFinalizedDeaths(currentTick);
        cleanupRecentInteractions(currentTick);

        return noLootDeaths;
    }

    public boolean wasDeathFinalized(EncounterDefinition encounter, NPC npc) {
        if (encounter == null || npc == null) {
            return false;
        }

        int currentTick = client.getTickCount();

        for (FinalizedDeath finalizedDeath : finalizedDeaths) {
            if (finalizedDeath == null
                    || !encounter.getEncounterId().equals(finalizedDeath.encounterId)) {
                continue;
            }

            if (currentTick - finalizedDeath.finalizedTick > FINALIZED_RETENTION_TICKS) {
                continue;
            }

            if ((finalizedDeath.npcId == -1 || finalizedDeath.npcId == npc.getId())
                    && (finalizedDeath.npcIndex == -1 || finalizedDeath.npcIndex == npc.getIndex())) {
                return true;
            }
        }

        return false;
    }

    public boolean wasEncounterRecentlyFinalized(EncounterDefinition encounter) {
        if (encounter == null) {
            return false;
        }

        int currentTick = client.getTickCount();

        for (FinalizedDeath finalizedDeath : finalizedDeaths) {
            if (finalizedDeath == null
                    || !encounter.getEncounterId().equals(finalizedDeath.encounterId)) {
                continue;
            }

            if (currentTick - finalizedDeath.finalizedTick <= FINALIZED_RETENTION_TICKS) {
                return true;
            }
        }

        return false;
    }

    /**
     * Marks an exact NPC death as completed.
     */
    public void finalizeDeath(EncounterDefinition encounter, NPC npc, int tick) {
        if (encounter == null || npc == null) {
            return;
        }

        removeFinalizedDeath(encounter.getEncounterId(), npc.getId(), npc.getIndex());

        finalizedDeaths.add(new FinalizedDeath(
                encounter.getEncounterId(),
                npc.getId(),
                npc.getIndex(),
                tick
        ));
    }

    /**
     * Marks a pending death as completed.
     */
    public void finalizeDeath(PendingDeath pendingDeath, int tick) {
        if (pendingDeath == null) {
            return;
        }

        removeFinalizedDeath(
                pendingDeath.encounterId,
                pendingDeath.npcId,
                pendingDeath.npcIndex
        );

        finalizedDeaths.add(new FinalizedDeath(
                pendingDeath.encounterId,
                pendingDeath.npcId,
                pendingDeath.npcIndex,
                tick
        ));
    }

    /**
     * Generic LootReceived does not identify the exact NPC.
     *
     * Only use this when there was no pending death available to provide
     * an exact NPC id/index.
     */
    public void finalizeEncounter(EncounterDefinition encounter, int tick) {
        if (encounter == null) {
            return;
        }

        finalizedDeaths.add(new FinalizedDeath(
                encounter.getEncounterId(),
                -1,
                -1,
                tick
        ));
    }

    public void clear() {
        pendingDeaths.clear();
        finalizedDeaths.clear();
        recentInteractions.clear();
    }

    /**
     * Resolves both official and player-created GROUND_LOOT encounters.
     *
     * Official encounter definitions always win by exact NPC ID.
     * Custom name + combat-level lookup remains only as the fallback for
     * player-created NPC variants which have not yet registered that ID.
     */
    private EncounterDefinition getGroundLootEncounter(NPC npc) {
        if (npc == null) {
            return null;
        }

        EncounterDefinition encounter = encounterRegistry.getByNpcId(npc.getId());

        if (encounter == null) {
            encounter = trackerManager.getCustomEncounterByNpc(npc.getName(), npc.getCombatLevel());
        }

        if (encounter == null
                || encounter.getLootType() != EncounterLootType.GROUND_LOOT) {
            return null;
        }

        return encounter;
    }

    private boolean wasLocalPlayerFightingNpc(NPC npc) {
        if (npc == null || client.getLocalPlayer() == null) {
            return false;
        }

        if (client.getLocalPlayer().getInteracting() == npc
                || npc.getInteracting() == client.getLocalPlayer()) {
            return true;
        }

        long npcKey = createNpcKey(npc.getId(), npc.getIndex());

        Integer interactionTick = recentInteractions.get(npcKey);

        if (interactionTick == null) {
            log.debug(
                    "Ignoring ground-loot NPC death because no local interaction was recorded: npc={} id={} index={} deathTick={}",
                    npc.getName(),
                    npc.getId(),
                    npc.getIndex(),
                    client.getTickCount()
            );

            return false;
        }

        if (client.getTickCount() - interactionTick > INTERACTION_RETENTION_TICKS) {
            recentInteractions.remove(npcKey);

            log.debug(
                    "Ignoring ground-loot NPC death because local interaction expired: npc={} id={} index={} interactionTick={} deathTick={}",
                    npc.getName(),
                    npc.getId(),
                    npc.getIndex(),
                    interactionTick,
                    client.getTickCount()
            );

            return false;
        }

        return true;
    }

    private void removeFinalizedDeath(String encounterId, int npcId, int npcIndex) {
        if (encounterId == null) {
            return;
        }

        finalizedDeaths.removeIf(finalizedDeath ->
                finalizedDeath != null
                        && encounterId.equals(finalizedDeath.encounterId)
                        && finalizedDeath.npcId == npcId
                        && finalizedDeath.npcIndex == npcIndex
        );
    }

    private void cleanupFinalizedDeaths(int currentTick) {
        finalizedDeaths.removeIf(finalizedDeath ->
                finalizedDeath == null
                        || currentTick - finalizedDeath.finalizedTick > FINALIZED_RETENTION_TICKS
        );
    }

    private void cleanupRecentInteractions(int currentTick) {
        recentInteractions.entrySet().removeIf(entry ->
                entry == null
                        || entry.getValue() == null
                        || currentTick - entry.getValue() > INTERACTION_RETENTION_TICKS
        );
    }

    private long createNpcKey(int npcId, int npcIndex) {
        return ((long) npcId << 32) | (npcIndex & 0xffffffffL);
    }

    private boolean canProcess() {
        return trackerManager.isActive()
                && client.getGameState() == GameState.LOGGED_IN;
    }

    public static class PendingDeath {
        private final String encounterId;
        private final int npcId;
        private final int npcIndex;
        private final int deathTick;
        private int despawnTick = -1;

        private PendingDeath(String encounterId, int npcId, int npcIndex, int deathTick) {
            this.encounterId = encounterId;
            this.npcId = npcId;
            this.npcIndex = npcIndex;
            this.deathTick = deathTick;
        }

        public String getEncounterId() {
            return encounterId;
        }

        public int getNpcId() {
            return npcId;
        }

        public int getNpcIndex() {
            return npcIndex;
        }

        public int getDeathTick() {
            return deathTick;
        }

        public int getDespawnTick() {
            return despawnTick;
        }

        public String createEventKey() {
            return "ground_loot_death|"
                    + deathTick
                    + "|"
                    + npcId
                    + "|"
                    + npcIndex;
        }
    }

    private static class FinalizedDeath {
        private final String encounterId;
        private final int npcId;
        private final int npcIndex;
        private final int finalizedTick;

        private FinalizedDeath(String encounterId, int npcId, int npcIndex, int finalizedTick) {
            this.encounterId = encounterId;
            this.npcId = npcId;
            this.npcIndex = npcIndex;
            this.finalizedTick = finalizedTick;
        }
    }
}

package com.harrystyles.drystreaktracker.ui;

import com.harrystyles.drystreaktracker.encounter.EncounterDefinition;
import com.harrystyles.drystreaktracker.encounter.EncounterDropDefinition;
