        setPreferredSize(new Dimension(0, PANEL_HEIGHT));

        setMinimumSize(new Dimension(0, PANEL_HEIGHT));

        setMaximumSize(new Dimension(Integer.MAX_VALUE, PANEL_HEIGHT));


        /*
         * Item information.
         */
