package com.harrystyles.drystreaktracker.encounter;

import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

import javax.inject.Singleton;

/**
 * Registry containing all encounter definitions.
 * <p>
 * Definitions can originate from multiple JSON resources:
 * <p>
 * encounters.json
 * loot-received-encounters.json
 */
@Singleton
public class EncounterRegistry {
    /**
     * Encounter ID -> encounter.
     */
    private final Map<String, EncounterDefinition> encountersById = new HashMap<>();

    /**
     * NPC ID -> encounter.
     * <p>
     * Used by NpcLootReceived.
     */
    private final Map<Integer, EncounterDefinition> encountersByNpcId = new HashMap<>();

    /**
     * LootReceived source name -> encounter.
     */
    private final Map<String, EncounterDefinition> encountersByLootSourceName = new HashMap<>();


    public void register(EncounterDefinition encounter) {
        if (encounter == null) {
            throw new IllegalArgumentException("Encounter cannot be null");
        }

        if (encounter.getEncounterId() == null || encounter.getEncounterId().trim().isEmpty()) {
            throw new IllegalArgumentException("Encounter ID cannot be null or empty");
        }

        String encounterId = encounter.getEncounterId().trim();

        if (encountersById.containsKey(encounterId)) {
            throw new IllegalStateException("Encounter ID already registered: " + encounterId);
        }

        /**
         * Validate NPC IDs before modifying the registry.
         */
        for (Integer npcId : encounter.getNpcIds()) {
            if (npcId == null) {
                continue;
            }

            EncounterDefinition existing = encountersByNpcId.get(npcId);

            if (existing != null) {
                throw new IllegalStateException("NPC ID " + npcId + " is already registered to " + existing.getEncounterId());
            }
        }

        /*
         * Validate LootReceived source names before modifying
         * the registry.
         */
        for (String lootSourceName : encounter.getLootSourceNames()) {
            if (lootSourceName == null || lootSourceName.trim().isEmpty()) {
                continue;
            }

            String normalizedName = normalizeLootSourceName(lootSourceName);

            EncounterDefinition existing = encountersByLootSourceName.get(normalizedName);

            if (existing != null) {
                throw new IllegalStateException("Loot source name '" + lootSourceName + "' is already registered to " + existing.getEncounterId()
                );
            }
        }

        /*
         * Register encounter by encounter ID.
         */
        encountersById.put(encounterId, encounter);

        /*
         * Register NPC IDs.
         */
        for (Integer npcId : encounter.getNpcIds()) {
            if (npcId != null) {
                encountersByNpcId.put(npcId, encounter);
            }
        }

        /*
         * Register LootReceived source names.
         */
        for (String lootSourceName : encounter.getLootSourceNames()) {
            if (lootSourceName != null && !lootSourceName.trim().isEmpty()) {
                encountersByLootSourceName.put(normalizeLootSourceName(lootSourceName), encounter);
            }
        }
    }


    public EncounterDefinition getById(String encounterId) {
        if (encounterId == null) {
            return null;
        }

        return encountersById.get(encounterId.trim());
    }


    public EncounterDefinition getByNpcId(int npcId) {
        return encountersByNpcId.get(npcId);
    }


    public EncounterDefinition getByLootSourceName(String sourceName) {
        if (sourceName == null || sourceName.trim().isEmpty()) {
            return null;
        }

        return encountersByLootSourceName.get(normalizeLootSourceName(sourceName));
    }

    public EncounterDefinition getGroundLootBySourceName(String sourceName) {
        if (sourceName == null || sourceName.trim().isEmpty()) {
            return null;
        }

        String normalizedName = normalizeLootSourceName(sourceName);

        for (EncounterDefinition encounter : encountersById.values()) {
            if (encounter == null || encounter.getLootType() != EncounterLootType.GROUND_LOOT) {
                continue;
            }

            if (encounter.getDisplayName() != null && normalizeLootSourceName(encounter.getDisplayName()).equals(normalizedName)) {
                return encounter;
            }

            if (encounter.matchesLootSource(sourceName)) {
                return encounter;
            }
        }

        return null;
    }


    public boolean containsNpcId(int npcId) {
        return encountersByNpcId.containsKey(npcId);
    }


    public boolean containsLootSourceName(String sourceName) {
        if (sourceName == null || sourceName.trim().isEmpty()) {
            return false;
        }

        return encountersByLootSourceName.containsKey(normalizeLootSourceName(sourceName));
    }

    /**
     * Removes one encounter from every registry index.
     *
     * Used for player-created encounters when changing
     * accounts or deleting a custom tracker.
     */
    public void unregister(String encounterId) {
        if (encounterId == null || encounterId.trim().isEmpty()) {
            return;
        }

        EncounterDefinition encounter = encountersById.remove(encounterId.trim());

        if (encounter == null) {
            return;
        }

        for (Integer npcId : encounter.getNpcIds()) {
            if (npcId == null) {
                continue;
            }

            EncounterDefinition registered = encountersByNpcId.get(npcId);

            if (registered == encounter) {
                encountersByNpcId.remove(npcId);
            }
        }

        for (String lootSourceName : encounter.getLootSourceNames()) {
            if (lootSourceName == null || lootSourceName.trim().isEmpty()) {
                continue;
            }

            String normalizedName = normalizeLootSourceName(lootSourceName);

            EncounterDefinition registered = encountersByLootSourceName.get(normalizedName);

            if (registered == encounter) {
                encountersByLootSourceName.remove(normalizedName);
            }
        }
    }

    public Collection<EncounterDefinition> getAll() {
        return Collections.unmodifiableCollection(encountersById.values());
    }


    public int size() {
        return encountersById.size();
    }


    public void clear() {
        encountersById.clear();
        encountersByNpcId.clear();
        encountersByLootSourceName.clear();
    }


    private String normalizeLootSourceName(String sourceName) {
        return sourceName.trim().toLowerCase();
    }
}

package com.harrystyles.drystreaktracker.encounter;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/**
 * Player-specific statistics for an encounter.
 *
 * @author Harry Styles
 */
public class EncounterStats {
    private String encounterId;

    private String displayName;

    private Set<Integer> npcIds = new HashSet<>();

    private int lastKnownKillcount;

    private int totalKillsTracked;

    private int currentDryStreak;

    private int totalTrackedDrops;

    /**
     * Dry Streak Tracker's kill number when the most recent
     * tracked drop was received.
     * <p>
     * This is based only on kills recorded while the plugin
     * is tracking the encounter, not the player's actual boss KC.
     * <p>
     * Example:
     * The plugin has tracked 10 General Graardor kills and a
     * unique is received on the 10th tracked kill.
     * lastDropKillcount = 10
     */
    private int lastDropKillcount;

    /**
     * -------------------NOT USED ANYMORE DO NOT DELETE---------------------------------
     * Player's actual boss KC when the most recent tracked
     * drop was received.
     * <p>
     * This value is obtained from RuneLite's stored boss
     * killcount and is saved as a snapshot when the drop occurs.
     * It does not continue increasing as the player gets more kills.
     * <p>
     * Example:
     * The plugin's 10th tracked General Graardor kill occurs
     * at the player's actual KC of 2,500 and a unique is received.
     * lastDropTotalKillcount = 2500
     */
    private int lastDropTotalKillcount; // DO NOT DELETE THIS. KEEPING SO IT DOESN'T POSSIBLY BREAK EXISTING GSON

    /**
     * Length of the dry streak that ended when the most
     * recent tracked drop was received.
     * <p>
     * This is captured immediately before currentDryStreak
     * is reset to 0.
     * <p>
     * Example:
     * A tracked drop is received after 684 dry kills.
     * lastCompletedDryStreak = 684
     */
    private int lastCompletedDryStreak;

    private int longestDryStreak;

    /**
     * Prevents repeated record notifications during the same
     * dry streak.
     * <p>
     * Once the current streak surpasses the previous record,
     * the notification toast is only sent once. This resets when
     * a tracked drop is received.
     */
    private boolean dryRecordNotificationSent;

    /**
     * Indicates that the most recently recorded kill was the
     * kill that surpassed the player's previous dry streak record.
     */
    private transient boolean newDryRecordThisKill;

    /**
     * Time this encounter was most recently completed.
     * <p>
     * Used to sort the sidebar so the most recently
     * killed encounter appears at the top.
     */
    private long lastActivityTime;

    /**
     * Item ID -> total quantity received.
     */
    private Map<Integer, Integer> receivedDrops = new HashMap<>();

    public EncounterStats() {
    }

    public EncounterStats(String encounterId, String displayName, Set<Integer> npcIds) {
        this.encounterId = encounterId;
        this.displayName = displayName;

        if (npcIds != null) {
            this.npcIds = new HashSet<>(npcIds);
        }
    }

    public String getEncounterId() {
        return encounterId;
    }

    public String getDisplayName() {
        return displayName;
    }

    public Set<Integer> getNpcIds() {
        return npcIds;
    }

    public int getLastKnownKillcount() {
        return lastKnownKillcount;
    }

    public int getTotalKillsTracked() {
        return totalKillsTracked;
    }

    public int getCurrentDryStreak() {
        return currentDryStreak;
    }

    public int getTotalTrackedDrops() {
        return totalTrackedDrops;
    }

    public int getLastDropKillcount() {
        return lastDropKillcount;
    }

    public int getLastDropTotalKillcount() {
        return lastDropTotalKillcount;
    }

    public int getLastCompletedDryStreak() {
        return lastCompletedDryStreak;
    }

    public int getLongestDryStreak() {
        return longestDryStreak;
    }

    public boolean isNewDryRecordThisKill() {
        return newDryRecordThisKill;
    }

    public long getLastActivityTime() {
        return lastActivityTime;
    }


    public Map<Integer, Integer> getReceivedDrops() {
        if (receivedDrops == null) {
            receivedDrops = new HashMap<>();
        }

        return receivedDrops;
    }

    public void setEncounterId(String encounterId) {
        this.encounterId = encounterId;
    }

    public void setDisplayName(String displayName) {
        this.displayName = displayName;
    }

    public void setNpcIds(Set<Integer> npcIds) {
        this.npcIds = npcIds == null ? new HashSet<>() : new HashSet<>(npcIds);
    }

    public void setLastKnownKillcount(int lastKnownKillcount) {
        this.lastKnownKillcount = lastKnownKillcount;
    }

    public void setTotalKillsTracked(int totalKillsTracked) {
        this.totalKillsTracked = totalKillsTracked;
    }

    public void setCurrentDryStreak(int currentDryStreak) {
        this.currentDryStreak = currentDryStreak;
    }

    public void setTotalTrackedDrops(int totalTrackedDrops) {
        this.totalTrackedDrops = totalTrackedDrops;
    }

    public void setLastDropKillcount(int lastDropKillcount) {
        this.lastDropKillcount = lastDropKillcount;
    }

    public void setLastDropTotalKillcount(int lastDropTotalKillcount) {
        this.lastDropTotalKillcount = lastDropTotalKillcount;
    }

    public void setLongestDryStreak(int longestDryStreak) {
        this.longestDryStreak = longestDryStreak;
    }

    public void setLastActivityTime(long lastActivityTime) {
        this.lastActivityTime = lastActivityTime;
    }

    public void setReceivedDrops(Map<Integer, Integer> receivedDrops) {
        this.receivedDrops = receivedDrops == null ? new HashMap<>() : new HashMap<>(receivedDrops);
    }

    /**
     * Reassigns these saved statistics to a different encounter
     * definition without changing any tracked progress.
     *
     * Used when a player-created encounter becomes an official
     * built-in encounter in a later plugin version.
     */
    public void migrateToDefinition(EncounterDefinition definition) {
        if (definition == null
                || definition.getEncounterId() == null
                || definition.getEncounterId().trim().isEmpty()) {
            return;
        }

        encounterId = definition.getEncounterId();
        displayName = definition.getDisplayName();
        npcIds = new HashSet<>(definition.getNpcIds());

        /*
         * All statistics remain untouched.
         *
         * This is only changing which encounter definition
         * owns the saved progress.
         */
        newDryRecordThisKill = false;
    }


    /**
     * Manually synchronizes the encounter counters with the player's
     * existing progress.
     * <p>
     * This is a data correction only. It must not trigger dry streak
     * records, notifications, drops, or any other encounter events.
     */
    public void setTrackingBaseline(int totalKillcount, int dryKillcount, int longestDryKillcount) {
        if (totalKillcount < 0 || dryKillcount < 0 || longestDryKillcount < 0) {
            return;
        }

        if (dryKillcount > totalKillcount || longestDryKillcount < dryKillcount) {
            return;
        }

        totalKillsTracked = totalKillcount;
        lastKnownKillcount = totalKillcount;
        currentDryStreak = dryKillcount;
        longestDryStreak = longestDryKillcount;

        /*
         * Manual synchronization must never represent a new record kill.
         */
        newDryRecordThisKill = false;

        /*
         * Treat the manually entered streak as an existing baseline.
         * Do not fire a record notification because of this edit.
         */
        dryRecordNotificationSent = false;

        lastActivityTime = System.currentTimeMillis();
    }

    public void recordDryKill(int currentKillcount) {

        /**
         * This flag only represents the kill currently
         * being processed.
         */
        newDryRecordThisKill = false;

        lastActivityTime = System.currentTimeMillis();

        lastKnownKillcount = currentKillcount;

        totalKillsTracked++;

        currentDryStreak++;

        /*
         * Check whether this kill beats the existing record
         * before updating longestDryStreak.
         *
         * Require at least one previous tracked drop so the
         * player's very first dry streak does not constantly
         * create a record with nothing meaningful to beat.
         */
        if (currentDryStreak > longestDryStreak) {
            if (!dryRecordNotificationSent && totalTrackedDrops > 0) {
                newDryRecordThisKill = true;

                dryRecordNotificationSent = true;
            }

            longestDryStreak = currentDryStreak;
        }
    }

    public void recordDrop(int currentKillcount, int itemId, int quantity) {
        lastActivityTime = System.currentTimeMillis();

        lastKnownKillcount = currentKillcount;

        totalKillsTracked++;
        totalTrackedDrops++;

        lastDropKillcount = currentKillcount;

        /*
         * The drop itself happened on the next kill after
         * currentDryStreak.
         *
         * Example:
         * 19 dry kills followed by a unique means the unique
         * took 20 kills.
         */
        int completedDropStreak = currentDryStreak + 1;

        /*
         * Check whether the kill that produced this drop also
         * established a new dry streak record.
         *
         * Do this BEFORE resetting the streak.
         */
        newDryRecordThisKill = totalTrackedDrops > 1 && !dryRecordNotificationSent && completedDropStreak > longestDryStreak;

        if (completedDropStreak > longestDryStreak) {
            longestDryStreak = completedDropStreak;
        }

        /*
         * Save how many kills it took to receive this drop,
         * including the kill that actually produced the unique.
         */
        lastCompletedDryStreak = completedDropStreak;

        /*
         * The drop ends the current streak.
         */
        dryRecordNotificationSent = false;

        currentDryStreak = 0;

        receivedDrops.merge(itemId, quantity, Integer::sum);
    }

    /**
     * Records an additional tracked drop from the same encounter
     * completion.
     * <p>
     * The encounter kill and dry streak have already been processed
     * by recordDrop(), so this must not increment the kill count or
     * reset the dry streak again.
     */
    public void recordAdditionalDropOnLastKill(int itemId, int quantity) {
        if (totalKillsTracked <= 0) {
            return;
        }

        lastActivityTime = System.currentTimeMillis();

        totalTrackedDrops++;

        lastDropKillcount = lastKnownKillcount;

        receivedDrops.merge(itemId, quantity, Integer::sum);
    }

    /**
     * Records a pet against the encounter kill which was
     * already processed through the normal loot event.
     *
     * Pets are detected separately from loot through the
     * RuneScape pet acquisition game message, so this method
     * must not increment totalKillsTracked.
     *
     * If the kill was originally recorded as dry, that dry
     * kill is converted into a qualifying drop.
     *
     * If another tracked drop was already received on the
     * same kill, the pet is added as an additional drop.
     */
    public void recordPetOnLastKill(int itemId, int quantity) {
        if (totalKillsTracked <= 0) {
            return;
        }

        lastActivityTime = System.currentTimeMillis();

        int petQuantity = Math.max(1, quantity);

        /*
         * The encounter kill itself has already been counted.
         *
         * Only increase the number of tracked drops.
         */
        totalTrackedDrops++;

        lastDropKillcount = lastKnownKillcount;

        /*
         * A positive currentDryStreak means the loot event was
         * originally processed as a dry kill.
         *
         * That streak already includes the kill which produced
         * the pet.
         */
        if (currentDryStreak > 0) {
            int completedDropStreak = currentDryStreak;

            newDryRecordThisKill = totalTrackedDrops > 1
                    && !dryRecordNotificationSent
                    && completedDropStreak > longestDryStreak;

            if (completedDropStreak > longestDryStreak) {
                longestDryStreak = completedDropStreak;
            }

            lastCompletedDryStreak = completedDropStreak;

            currentDryStreak = 0;

            dryRecordNotificationSent = false;
        } else {
            /*
             * A normal tracked drop was already recorded on this
             * kill, so its dry streak has already been reset.
             */
            newDryRecordThisKill = false;
        }

        receivedDrops.merge(itemId, petQuantity, Integer::sum);
    }

    /**
     * Adds a missing historical tracked drop without changing
     * any kill count or dry streak statistics.
     */
    public void addMissingDrop(int itemId, int quantity) {
        if (itemId <= 0 || quantity <= 0) {
            return;
        }

        totalTrackedDrops++;

        getReceivedDrops().merge(itemId, quantity, Integer::sum);
    }

}

