package com.harrystyles.drystreaktracker.encounter;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.HashSet;
import java.util.Set;

import javax.inject.Inject;
import javax.inject.Singleton;

import lombok.extern.slf4j.Slf4j;

/**
 * Loads encounter definitions from JSON resources.
 * <p>
 * encounters.json
 * -> NpcLootReceived / NPC ID based encounters.
 * <p>
 * loot-received-encounters.json
 * -> LootReceived / source-name based encounters.
 * <p>
 * The JSON definitions do NOT need a lootType property.
 * The loader assigns the correct type automatically based
 * on the resource being loaded.
 */
@Slf4j
@Singleton
public class EncounterDefinitionLoader {
    private static final String NPC_RESOURCE = "/encounters.json";

    private static final String LOOT_RECEIVED_RESOURCE = "/loot-received-encounters.json";


    private final Gson gson;


    @Inject
    public EncounterDefinitionLoader(Gson gson) {
        this.gson = gson;
    }


    /**
     * Loads both encounter resources into the registry.
     */
    public void loadInto(EncounterRegistry registry) {
        if (registry == null) {
            throw new IllegalArgumentException("EncounterRegistry cannot be null");
        }

        registry.clear();

        /*
         * Normal NPC death encounters.
         */
        EncounterDefinition[] npcDefinitions = loadResource(NPC_RESOURCE, EncounterLootType.GROUND_LOOT);

        for (EncounterDefinition definition : npcDefinitions) {
            validate(definition);

            registry.register(definition);
        }

        /*
         * Generic LootReceived encounters.
         */
        EncounterDefinition[] lootReceivedDefinitions = loadResource(LOOT_RECEIVED_RESOURCE, EncounterLootType.LOOT_RECEIVED);

        for (EncounterDefinition definition : lootReceivedDefinitions) {
            validate(definition);

            registry.register(definition);
        }

        log.info("Encounter registry initialized with {} encounters", registry.size());
    }


    /**
     * Loads one JSON resource and assigns every encounter
     * in that file the supplied loot type.
     */
    private EncounterDefinition[] loadResource(String resource, EncounterLootType lootType) {
        InputStream inputStream = getClass().getResourceAsStream(resource);

        if (inputStream == null) {
            /**
             * encounters.json is required.
             *
             * loot-received-encounters.json may legitimately be
             * empty/not added yet during development, so return an
             * empty array for that file.
             */
            if (lootType == EncounterLootType.LOOT_RECEIVED) {
                log.warn("Optional LootReceived encounter resource not found: {}", resource);

                return new EncounterDefinition[0];
            }

            throw new IllegalStateException("Encounter resource not found: " + resource);
        }

        try (Reader reader = new InputStreamReader(inputStream, StandardCharsets.UTF_8)) {
            EncounterDefinition[] definitions = gson.fromJson(reader, EncounterDefinition[].class);

            if (definitions == null) {
                return new EncounterDefinition[0];
            }

            for (EncounterDefinition definition : definitions) {
                if (definition == null) {
                    continue;
                }

                /**
                 * Important:
                 *
                 * Ignore any lootType from JSON and force the
                 * correct type based on the resource.
                 */
                definition.setLootType(lootType);
            }

            log.info("Loaded {} encounters from {} as {}", definitions.length, resource, lootType);

            return definitions;
        } catch (JsonParseException e) {
            throw new IllegalStateException("Invalid encounter JSON: " + resource, e);
        } catch (Exception e) {
            throw new IllegalStateException("Could not load encounter JSON: " + resource, e);
        }
    }


    private void validate(EncounterDefinition definition) {
        if (definition == null) {
            throw new IllegalStateException("Encounter definition cannot be null");
        }

        if (definition.getEncounterId() == null || definition.getEncounterId().trim().isEmpty()) {
            throw new IllegalStateException("Encounter definition has no encounterId");
        }

        if (definition.getDisplayName() == null || definition.getDisplayName().trim().isEmpty()) {
            throw new IllegalStateException("Encounter " + definition.getEncounterId() + " has no displayName");
        }

        String imageFileName = definition.getImageFileName();

        if (imageFileName != null && !imageFileName.trim().isEmpty()) {
            String fileName = imageFileName.trim();

            if (fileName.contains("/") || fileName.contains("\\") || fileName.contains(":")) {
                throw new IllegalStateException(
                        "[DRY STREAK TRACKER]: Encounter " + definition.getEncounterId() + " has an invalid imageFileName: " + fileName);
            }
        }

        if (definition.getLootType() == null) {
            throw new IllegalStateException("Encounter " + definition.getEncounterId() + " has no internally assigned loot type");
        }

        if (definition.getTrackedDrops() == null) {
            throw new IllegalStateException("Encounter " + definition.getEncounterId() + " has null trackedDrops");
        }

        Set<Integer> configuredDropIds = new HashSet<>();

        for (EncounterDropDefinition drop : definition.getTrackedDrops()) {
            if (drop == null) {
                throw new IllegalStateException("Encounter " + definition.getEncounterId() + " contains a null tracked drop");
            }

            if (drop.getItemId() <= 0) {
                throw new IllegalStateException("Encounter " + definition.getEncounterId() + " contains invalid tracked drop item ID " + drop.getItemId());
            }

            if (!configuredDropIds.add(drop.getItemId())) {
                throw new IllegalStateException("Encounter " + definition.getEncounterId() + " contains duplicate tracked drop item ID " + drop.getItemId());
            }
        }

        if (definition.getPetDropIds() == null) {
            throw new IllegalStateException("Encounter " + definition.getEncounterId() + " has null petDropIds");
        }

        /**
         * encounters.json
         *
         * Must identify an NPC by NPC ID.
         */
        if (definition.getLootType() == EncounterLootType.GROUND_LOOT) {
            if (definition.getNpcIds().isEmpty()) {
                throw new IllegalStateException("NPC encounter " + definition.getEncounterId() + " from " + NPC_RESOURCE + " must have at least one npcId"
                );
            }

            /**
             * Prevent accidentally putting LootReceived
             * configuration in encounters.json.
             */
            if (!definition.getLootSourceNames().isEmpty()) {
                log.warn("Encounter {} is in {} but contains lootSourceNames. " + "lootSourceNames will not be used.", definition.getEncounterId(), NPC_RESOURCE);
            }

            return;
        }

        /**
         * loot-received-encounters.json
         *
         * Must identify the encounter using the name returned by
         * LootReceived.getName().
         */
        if (definition.getLootType() == EncounterLootType.LOOT_RECEIVED) {
            if (definition.getLootSourceNames().isEmpty()) {
                throw new IllegalStateException("LootReceived encounter " + definition.getEncounterId() + " from " + LOOT_RECEIVED_RESOURCE + " must have at least one lootSourceName");
            }
        }
    }
}

package com.harrystyles.drystreaktracker.encounter;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * Static definition of an encounter.
 * Definitions may be loaded from:
 * <p>
 * encounters.json
 * -> NpcLootReceived encounters
 * <p>
 * loot-received-encounters.json
 * -> LootReceived encounters
 * <p>
 * The JSON itself does not need to contain lootType.
 * EncounterDefinitionLoader assigns it automatically depending
 * on which resource the definition came from
 */
public class EncounterDefinition {
    private String encounterId;

    private String displayName;

    private Integer combatLevel;

    private static final String WIKI_IMAGE_BASE_URL = "https://oldschool.runescape.wiki/images/";

    private String imageFileName;

    /**
     * Assigned internally by EncounterDefinitionLoader.
     * <p>
     * This does NOT need to appear in JSON.
     */
    private EncounterLootType lootType;

    /**
     * NPC IDs belonging to this encounter.
     * <p>
     * Used by encounters.json / NpcLootReceived.
     */
    private Set<Integer> npcIds = new HashSet<>();

    /**
     * Names supplied by LootReceived.getName().
     * <p>
     * Used by loot-received-encounters.json.
     */
    private Set<String> lootSourceNames = new HashSet<>();

    /**
     * Drops which may be tracked for this encounter.
     *
     * Each drop defines whether it is enabled by default.
     * Players may override these defaults per account.
     */
    private List<EncounterDropDefinition> trackedDrops = new ArrayList<>();

    /**
     * Pet item IDs.
     * <p>
     * These count only when trackPets is enabled.
     */
    private Set<Integer> petDropIds = new HashSet<>();


    public EncounterDefinition() {
    }


    public String getEncounterId() {
        return encounterId;
    }


    public void setEncounterId(String encounterId) {
        this.encounterId = encounterId;
    }


    public String getDisplayName() {
        return displayName;
    }


    public void setDisplayName(String displayName) {
        this.displayName = displayName;
    }

    public Integer getCombatLevel() {
        return combatLevel;
    }

    public void setCombatLevel(Integer combatLevel) {
        this.combatLevel = combatLevel;
    }

    public String getImageFileName() {
        return imageFileName;
    }


    public void setImageFileName(String imageFileName) {
        this.imageFileName = imageFileName;
    }


    public String getImageUrl() {
        if (imageFileName == null || imageFileName.trim().isEmpty()) {
            return null;
        }

        String fileName = imageFileName.trim();

        /*
         * Encounter JSON is only allowed to provide a Wiki
         * image filename, not an arbitrary URL or path.
         */
        if (fileName.contains("/") || fileName.contains("\\") || fileName.contains(":")) {
            return null;
        }

        return WIKI_IMAGE_BASE_URL + fileName;
    }


    public EncounterLootType getLootType() {
        return lootType;
    }


    public void setLootType(EncounterLootType lootType) {
        this.lootType = lootType;
    }


    public Set<Integer> getNpcIds() {
        if (npcIds == null) {
            npcIds = new HashSet<>();
        }

        return npcIds;
    }


    public void setNpcIds(Set<Integer> npcIds) {
        this.npcIds = npcIds == null ? new HashSet<>() : new HashSet<>(npcIds);
    }


    public Set<String> getLootSourceNames() {
        if (lootSourceNames == null) {
            lootSourceNames = new HashSet<>();
        }

        return lootSourceNames;
    }


    public void setLootSourceNames(Set<String> lootSourceNames) {
        this.lootSourceNames = lootSourceNames == null ? new HashSet<>() : new HashSet<>(lootSourceNames);
    }


    public List<EncounterDropDefinition> getTrackedDrops() {
        if (trackedDrops == null) {
            trackedDrops = new ArrayList<>();
        }

        return trackedDrops;
    }


    public void setTrackedDrops(List<EncounterDropDefinition> trackedDrops) {
        this.trackedDrops = trackedDrops == null ? new ArrayList<>() : new ArrayList<>(trackedDrops);
    }


    public EncounterDropDefinition getTrackedDrop(int itemId) {
        for (EncounterDropDefinition drop : getTrackedDrops()) {
            if (drop != null && drop.getItemId() == itemId) {
                return drop;
            }
        }

        return null;
    }


    public Set<Integer> getPetDropIds() {
        if (petDropIds == null) {
            petDropIds = new HashSet<>();
        }

        return petDropIds;
    }


    public void setPetDropIds(
            Set<Integer> petDropIds) {
        this.petDropIds = petDropIds == null ? new HashSet<>() : new HashSet<>(petDropIds);
    }


    public boolean matchesNpc(int npcId) {
        return getNpcIds().contains(npcId);
    }


    public boolean matchesLootSource(String sourceName) {
        if (sourceName == null) {
            return false;
        }

        String normalized = sourceName.trim();

        for (String configuredSource : getLootSourceNames()) {
            if (configuredSource != null && configuredSource.trim().equalsIgnoreCase(normalized)) {
                return true;
            }
        }

        return false;
    }


    public boolean isTrackedDrop(int itemId) {
        return getTrackedDrop(itemId) != null;
    }


    public boolean isPetDrop(int itemId) {
        return getPetDropIds().contains(itemId);
    }


    public boolean isQualifyingDrop(int itemId, boolean trackPets) {
        if (isTrackedDrop(itemId)) {
            return true;
        }

        return trackPets && isPetDrop(itemId);
    }


    @Override
    public String toString() {
        return "EncounterDefinition{" +
                "encounterId='" + encounterId + '\'' +
                ", displayName='" + displayName + '\'' +
                ", lootType=" + lootType +
                ", npcIds=" + npcIds +
                ", lootSourceNames=" + lootSourceNames +
                ", trackedDrops=" + trackedDrops +
                ", petDropIds=" + petDropIds +
                '}';
    }
}

package com.harrystyles.drystreaktracker.encounter.tracking;

import com.harrystyles.drystreaktracker.encounter.*;
import com.harrystyles.drystreaktracker.storage.DryStreakStorage;

import java.util.*;

import javax.inject.Inject;
import javax.inject.Singleton;

import lombok.extern.slf4j.Slf4j;

/**
 * Handles all player encounter tracking.
 * <p>
 * Tracking data is loaded and saved per RuneScape account.
 *
 * @author Harry Styles
 */
@Slf4j
@Singleton
public class EncounterTrackerManager {
    /**
     * Maximum number of recently processed kill events
     * kept in memory to prevent duplicate event handling.
     */
    private static final int MAX_PROCESSED_KILL_EVENTS = 100;

    private final EncounterRegistry encounterRegistry;
    private final DryStreakStorage storage;

    /**
     * Tracking data for the currently logged-in player.
     */
    private PlayerTrackingData trackingData;

    /**
     * RuneScape character currently being tracked.
     */
    private String currentPlayerName;

    /**
     * Whether the tracker currently has an active
     * logged-in RuneScape character.
     */
    private boolean active;

    /**
     * Recently processed kill event fingerprints.
     */
    private final Set<String> processedKillEvents = new HashSet<>();

    @Inject
    public EncounterTrackerManager(EncounterRegistry encounterRegistry, DryStreakStorage storage) {
        this.encounterRegistry = encounterRegistry;
        this.storage = storage;
    }

    /**
     * Starts tracking for a specific RuneScape account.
     * <p>
     * If the same account is already active, nothing happens.
     *
     * @param playerName RuneScape character name.
     */
    public void startForPlayer(String playerName) {
        if (playerName == null || playerName.trim().isEmpty()) {
            log.warn("Cannot start tracker: player name is empty");

            return;
        }

        String normalizedName = playerName.trim();

        if (active && currentPlayerName != null && currentPlayerName.equalsIgnoreCase(normalizedName)) {
            log.debug("Tracker already active for {}", normalizedName);

            return;
        }

        if (active) {
            stopForPlayer();
        }

        currentPlayerName = normalizedName;

        trackingData = storage.load(currentPlayerName);

        if (trackingData == null) {
            trackingData = new PlayerTrackingData();
        }

        processedKillEvents.clear();

        boolean customEncountersMigrated = registerCustomEncounters();

        active = true;

        if (customEncountersMigrated) {
            save();
        }

        log.info(
                "Started tracking for account {}. Loaded {} tracked encounters and {} custom encounters.",
                currentPlayerName,
                trackingData.getEncounters().size(),
                trackingData.getCustomEncounters().size()
        );
    }

    /**
     * Stops tracking the currently logged-in account.
     * <p>
     * The account's data is saved before the tracker
     * becomes inactive.
     */
    public void stopForPlayer() {
        if (!active) {
            return;
        }

        log.info("Stopping tracker for account {}", currentPlayerName);

        save();

        /*
         * Custom encounter definitions belong only to the
         * currently logged-in RuneScape account.
         */
        unregisterCustomEncounters();

        processedKillEvents.clear();

        trackingData = null;
        currentPlayerName = null;
        active = false;
    }

    /**
     * Called when the plugin itself starts.
     * <p>
     * Tracking is intentionally NOT started here because
     * the player may not be logged in yet.
     */
    public void start() {
        trackingData = null;
        currentPlayerName = null;
        active = false;

        processedKillEvents.clear();

        log.info("Encounter tracker initialized. " + "Waiting for player login.");
    }

    /**
     * Called when the plugin shuts down.
     */
    public void stop() {
        stopForPlayer();
        processedKillEvents.clear();
    }

    /**
     * Saves the currently active player's data.
     */
    public void save() {
        if (!isActive()) {
            return;
        }

        storage.save(currentPlayerName, trackingData);
    }

    /**
     * Records a completed encounter kill.
     * <p>
     * A kill may either have a tracked drop or be dry.
     *
     * @param encounterId  encounter being tracked
     * @param killEventKey unique fingerprint for this kill event
     * @param dropItemId   tracked drop item ID, or null if dry
     * @param dropQuantity quantity received from the drop
     * @return true if the kill was recorded
     */
    public boolean recordKill(String encounterId, String killEventKey, Integer dropItemId, int dropQuantity) {
        if (!isActive()) {
            log.debug("Ignoring kill because no player is logged in");

            return false;
        }

        if (encounterId == null || encounterId.trim().isEmpty()) {
            log.warn("Cannot record kill: encounter ID is null or empty");

            return false;
        }

        EncounterDefinition definition = encounterRegistry.getById(encounterId);

        if (definition == null) {
            log.warn("Cannot record kill: unknown encounter {}", encounterId);

            return false;
        }

        if (killEventKey != null && !killEventKey.isEmpty()) {
            if (!registerKillEvent(killEventKey)) {
                log.debug("Duplicate kill event ignored: {}", killEventKey);

                return false;
            }
        }

        EncounterStats stats = trackingData.getOrCreateEncounter(definition);

        log.info("[DST DEBUG] recordKill entered: encounter='{}' currentKC={} currentDry={} dropItemId={} quantity={} eventKey='{}'",
                encounterId,
                stats.getTotalKillsTracked(),
                stats.getCurrentDryStreak(),
                dropItemId,
                dropQuantity,
                killEventKey);

        int newKillcount = stats.getLastKnownKillcount() + 1;

        if (dropItemId != null) {
            stats.recordDrop(newKillcount, dropItemId, dropQuantity);

            log.info("{} kill #{} recorded with tracked drop. " + "Current dry streak: {}", definition.getDisplayName(), newKillcount, stats.getCurrentDryStreak());
        } else {
            stats.recordDryKill(newKillcount);

            log.debug("{} kill #{} recorded as dry. " + "Current dry streak: {}", definition.getDisplayName(), newKillcount, stats.getCurrentDryStreak());
        }

        log.info("[DST DEBUG] recordKill completed: encounter='{}' newKC={} newDry={} totalDrops={}",
                encounterId,
                stats.getTotalKillsTracked(),
                stats.getCurrentDryStreak(),
                stats.getTotalTrackedDrops());

        save();

        return true;
    }

    /**
     * Records another tracked drop from an encounter kill which
     * has already been recorded.
     */
    public boolean recordAdditionalDropForLastKill(String encounterId, int itemId, int quantity) {
        if (!isActive()) {
            return false;
        }

        if (encounterId == null || encounterId.trim().isEmpty()) {
            return false;
        }

        EncounterDefinition definition = encounterRegistry.getById(encounterId);

        if (definition == null || !isDropEnabled(encounterId, itemId)) {
            return false;
        }

        EncounterStats stats = trackingData.getEncounter(encounterId);

        if (stats == null || stats.getTotalKillsTracked() <= 0) {
            return false;
        }

        stats.recordAdditionalDropOnLastKill(itemId, quantity);

        save();

        log.info("{} additional tracked drop {} recorded on existing kill #{}", definition.getDisplayName(), itemId, stats.getLastKnownKillcount());

        return true;
    }

    /**
     * Records a pet against the most recently completed kill
     * for an encounter.
     *
     * The encounter kill has already been processed through
     * NpcLootReceived or LootReceived, so this method does not
     * create another kill.
     */
    public boolean recordPetForLastKill(String encounterId, int petItemId) {
        if (!isActive()) {
            return false;
        }

        if (encounterId == null || encounterId.trim().isEmpty()) {
            return false;
        }

        EncounterDefinition definition = encounterRegistry.getById(encounterId);

        if (definition == null) {
            return false;
        }

        if (!definition.isPetDrop(petItemId)) {
            log.warn("Item {} is not configured as a pet for {}", petItemId, encounterId);

            return false;
        }

        EncounterStats stats = trackingData.getEncounter(encounterId);

        if (stats == null || stats.getTotalKillsTracked() <= 0) {
            return false;
        }

        stats.recordPetOnLastKill(petItemId, 1);

        save();

        log.info("{} pet {} recorded on existing kill #{}", definition.getDisplayName(), petItemId, stats.getLastKnownKillcount());

        return true;
    }

    /**
     * Registers a kill event so the same event cannot
     * immediately be processed twice.
     * <p>
     * The set uses a rolling window. Once the maximum size
     * is reached, the oldest information is discarded by
     * clearing the set.
     */
    private boolean registerKillEvent(String killEventKey) {
        if (processedKillEvents.contains(killEventKey)) {
            return false;
        }

        /*
         * Keep the set bounded.
         *
         * Do this BEFORE adding the new event so the set
         * never grows beyond the configured limit.
         */
        if (processedKillEvents.size() >= MAX_PROCESSED_KILL_EVENTS) {
            processedKillEvents.clear();
        }

        processedKillEvents.add(killEventKey);

        return true;
    }

    /**
     * Gets statistics for an encounter.
     *
     * @param encounterId encounter ID
     * @return encounter statistics, or null if none exist
     */
    public EncounterStats getStats(String encounterId) {
        if (!isActive()) {
            return null;
        }

        return trackingData.getEncounter(
                encounterId
        );
    }

    /**
     * Gets all player tracking data.
     *
     * @return current player's tracking data, or null
     * if nobody is logged in
     */
    public PlayerTrackingData getTrackingData() {
        return trackingData;
    }

    /**
     * Returns the currently active RuneScape account.
     *
     * @return player name, or null if nobody is logged in
     */
    public String getCurrentPlayerName() {
        return currentPlayerName;
    }

    /**
     * Returns whether a player is currently being tracked.
     */
    public boolean isActive() {
        return active && currentPlayerName != null && trackingData != null;
    }

    /**
     * Clears duplicate-event tracking.
     * <p>
     * This does NOT clear any saved encounter statistics.
     */
    public void clearProcessedKillEvents() {
        processedKillEvents.clear();
    }

    /**
     * Clears all saved data for the currently logged-in
     * account.
     * <p>
     * The player remains logged in and tracking remains active,
     * but all encounter statistics are reset.
     */
    public void clearAllData() {
        if (!isActive()) {
            log.debug("Cannot clear account data: no player is logged in");

            return;
        }

        String playerName = currentPlayerName;

        unregisterCustomEncounters();

        trackingData = new PlayerTrackingData();

        processedKillEvents.clear();

        storage.clear(playerName);

        save();

        log.info("Cleared all tracking data for account {}", playerName);
    }

    /**
     * Manually synchronizes an encounter with the player's
     * existing total KC and current dry streak.
     */
    public boolean setEncounterKillcounts(String encounterId, int totalKillcount, int dryKillcount, int longestDryKillcount) {
        if (!isActive()) {
            return false;
        }

        if (encounterId == null || encounterId.trim().isEmpty()) {
            return false;
        }

        if (totalKillcount < 0 || dryKillcount < 0 || longestDryKillcount < 0) {
            return false;
        }

        if (dryKillcount > totalKillcount || longestDryKillcount < dryKillcount) {
            return false;
        }

        EncounterDefinition definition = encounterRegistry.getById(encounterId);

        if (definition == null) {
            return false;
        }

        EncounterStats stats = trackingData.getOrCreateEncounter(definition);

        if (stats == null) {
            return false;
        }

        stats.setTrackingBaseline(totalKillcount, dryKillcount, longestDryKillcount);

        save();

        log.info("Manually synchronized {} to total KC {}, dry KC {}, and longest dry KC {}", encounterId, totalKillcount, dryKillcount, longestDryKillcount);

        return true;
    }

    /**
     * Clears all saved tracking data for one encounter.
     * <p>
     * The rest of the player's tracked encounters remain
     * unchanged.
     *
     * @param encounterId encounter to clear
     */
    public void clearEncounterData(
            String encounterId) {
        if (!isActive()) {
            log.debug("Cannot clear encounter data: no player is logged in");

            return;
        }

        if (encounterId == null || encounterId.trim().isEmpty()) {
            return;
        }

        trackingData.removeEncounter(encounterId);

        /*
         * Save immediately so the cleared encounter does not
         * return after restarting RuneLite.
         */
        save();

        log.info("Cleared tracking data for encounter {}", encounterId);
    }

    public void recordRecentDrop(String encounterId, int itemId, int quantity, long geValue) {
        if (!isActive()) {
            return;
        }

        EncounterDefinition definition = encounterRegistry.getById(encounterId);

        EncounterStats stats = trackingData.getEncounter(encounterId);

        if (definition == null || stats == null) {
            return;
        }

        RecentDrop recentDrop = new RecentDrop(
                currentPlayerName,
                encounterId,
                definition.getDisplayName(),
                definition.getImageUrl(),
                itemId,
                quantity,
                stats.getLastCompletedDryStreak(),
                geValue,
                System.currentTimeMillis()
        );

        trackingData.addRecentDrop(recentDrop);

        save();
    }

    public java.util.List<RecentDrop> getRecentDrops() {
        if (!isActive()) {
            return java.util.Collections.emptyList();
        }

        return trackingData.getRecentDrops();
    }

    public void clearRecentDrops() {
        if (!isActive()) {
            return;
        }

        trackingData.clearRecentDrops();

        save();

        log.info("Cleared recent drops for account {}", currentPlayerName);
    }

    public void removeRecentDrop(RecentDrop recentDrop) {
        if (!isActive() || recentDrop == null) {
            return;
        }

        trackingData.removeRecentDrop(recentDrop);

        save();

        log.info(
                "Removed recent drop {} from {}",
                recentDrop.getItemId(),
                recentDrop.getEncounterName()
        );
    }

    public void clearTrackerData() {
        if (!isActive()) {
            return;
        }

        trackingData.clearEncounters();

        processedKillEvents.clear();

        save();

        log.info("Cleared tracker data for account {}", currentPlayerName);
    }

    /**
     * Returns whether a configurable drop is currently enabled
     * for the active player.
     */
    public boolean isDropEnabled(String encounterId, int itemId) {
        if (!isActive()) {
            return false;
        }

        if (encounterId == null || encounterId.trim().isEmpty()) {
            return false;
        }

        EncounterDefinition definition = encounterRegistry.getById(encounterId);

        if (definition == null) {
            return false;
        }

        EncounterDropDefinition drop = definition.getTrackedDrop(itemId);

        if (drop == null) {
            return false;
        }

        EncounterDropPreferences preferences = trackingData.getDropPreferences(encounterId);

        if (preferences.getEnabled().contains(itemId)) {
            return true;
        }

        if (preferences.getDisabled().contains(itemId)) {
            return false;
        }

        return drop.isEnabledByDefault();
    }


    /**
     * Changes whether one configurable drop is enabled for the
     * active player.
     *
     * If the selected state matches the encounter's default,
     * any stored override is removed.
     */
    public boolean setDropEnabled(String encounterId, int itemId, boolean enabled, boolean saveImmediately) {
        if (!isActive()) {
            return false;
        }

        if (encounterId == null || encounterId.trim().isEmpty()) {
            return false;
        }

        EncounterDefinition definition = encounterRegistry.getById(encounterId);

        if (definition == null) {
            return false;
        }

        EncounterDropDefinition drop = definition.getTrackedDrop(itemId);

        if (drop == null) {
            return false;
        }

        EncounterDropPreferences preferences = trackingData.getOrCreateDropPreferences(encounterId);

        preferences.getEnabled().remove(itemId);
        preferences.getDisabled().remove(itemId);

        if (enabled != drop.isEnabledByDefault()) {
            if (enabled) {
                preferences.getEnabled().add(itemId);
            } else {
                preferences.getDisabled().add(itemId);
            }
        }

        if (preferences.getEnabled().isEmpty() && preferences.getDisabled().isEmpty()) {
            trackingData.clearDropPreferences(encounterId);
        }

        if (saveImmediately) {
            save();
        }

        return true;
    }

    public boolean setDropEnabled(String encounterId, int itemId, boolean enabled) {
        return setDropEnabled(encounterId, itemId, enabled, true);
    }

    /**
     * Resets all configurable drops for one encounter back to
     * the defaults supplied by the encounter definition.
     */
    public boolean resetDropPreferences(String encounterId) {
        if (!isActive()) {
            return false;
        }

        if (encounterId == null || encounterId.trim().isEmpty()) {
            return false;
        }

        if (encounterRegistry.getById(encounterId) == null) {
            return false;
        }

        trackingData.clearDropPreferences(encounterId);

        save();

        return true;
    }

    public EncounterDefinition getCustomEncounterByNpcId(int npcId) {
        if (!isActive()) {
            return null;
        }

        return trackingData.getCustomEncounterByNpcId(npcId);
    }

    public EncounterDefinition getCustomEncounterByNpc(String npcName, int combatLevel) {
        if (!isActive()) {
            return null;
        }

        return trackingData.getCustomEncounterByNpc(npcName, combatLevel);
    }

    public boolean isCustomEncounter(String encounterId) {
        if (!isActive() || encounterId == null) {
            return false;
        }

        return trackingData.getCustomEncounter(encounterId) != null;
    }

    public boolean saveCustomEncounter(EncounterDefinition encounter) {
        if (!isActive() || encounter == null) {
            return false;
        }

        if (encounter.getEncounterId() == null || encounter.getEncounterId().trim().isEmpty()) {
            return false;
        }

        if (encounter.getNpcIds().isEmpty()) {
            return false;
        }

        encounter.setLootType(EncounterLootType.GROUND_LOOT);

        EncounterDefinition oldCustomEncounter =
                trackingData.getCustomEncounter(encounter.getEncounterId());

        /*
         * During editing the existing definition must temporarily
         * be removed from the registry so its NPC ID is available.
         */
        if (oldCustomEncounter != null) {
            encounterRegistry.unregister(oldCustomEncounter.getEncounterId());
        }

        for (Integer npcId : encounter.getNpcIds()) {
            if (npcId == null) {
                continue;
            }

            EncounterDefinition conflict = encounterRegistry.getByNpcId(npcId);

            if (conflict != null) {
                if (oldCustomEncounter != null) {
                    try {
                        encounterRegistry.register(oldCustomEncounter);
                    } catch (Exception restoreError) {
                        log.warn(
                                "Could not restore custom encounter {} after registration conflict",
                                oldCustomEncounter.getEncounterId(),
                                restoreError
                        );
                    }
                }

                log.warn(
                        "Cannot save custom encounter {} because NPC ID {} is already registered to {}",
                        encounter.getEncounterId(),
                        npcId,
                        conflict.getEncounterId()
                );

                return false;
            }
        }

        try {
            encounterRegistry.register(encounter);
        } catch (Exception e) {
            if (oldCustomEncounter != null) {
                try {
                    encounterRegistry.register(oldCustomEncounter);
                } catch (Exception restoreError) {
                    log.warn(
                            "Could not restore custom encounter {} after failed update",
                            oldCustomEncounter.getEncounterId(),
                            restoreError
                    );
                }
            }

            log.warn("Could not register custom encounter {}", encounter.getEncounterId(), e);

            return false;
        }

        trackingData.putCustomEncounter(encounter);

        save();

        log.info(
                "Saved custom encounter {} with {} NPC ID(s) and {} tracked drop(s)",
                encounter.getEncounterId(),
                encounter.getNpcIds().size(),
                encounter.getTrackedDrops().size()
        );

        return true;
    }

    public boolean removeCustomEncounter(String encounterId) {
        if (!isActive() || encounterId == null || encounterId.trim().isEmpty()) {
            return false;
        }

        EncounterDefinition encounter = trackingData.getCustomEncounter(encounterId);

        if (encounter == null) {
            return false;
        }

        encounterRegistry.unregister(encounterId);

        trackingData.removeCustomEncounter(encounterId);
        trackingData.removeEncounter(encounterId);
        trackingData.clearDropPreferences(encounterId);

        processedKillEvents.clear();

        save();

        log.info("Removed custom encounter {}", encounterId);

        return true;
    }

    private boolean migrateCustomEncounterToBuiltIn(EncounterDefinition customEncounter, EncounterDefinition builtInEncounter) {
        if (trackingData == null
                || customEncounter == null
                || builtInEncounter == null
                || customEncounter.getEncounterId() == null
                || builtInEncounter.getEncounterId() == null) {
            return false;
        }

        String customEncounterId = customEncounter.getEncounterId();
        String builtInEncounterId = builtInEncounter.getEncounterId();

        EncounterStats customStats = trackingData.getEncounter(customEncounterId);
        EncounterStats builtInStats = trackingData.getEncounter(builtInEncounterId);

        /*
         * If both encounter IDs already contain statistics, do not
         * automatically combine them.
         *
         * Their tracked kill ranges may overlap, so adding the values
         * together could double-count player progress.
         */
        if (customStats != null && builtInStats != null) {
            log.warn(
                    "Cannot automatically migrate custom encounter {} to built-in encounter {} because both already contain saved statistics",
                    customEncounterId,
                    builtInEncounterId
            );

            return false;
        }

        if (customStats != null) {
            trackingData.removeEncounter(customEncounterId);

            customStats.migrateToDefinition(builtInEncounter);

            trackingData.putEncounter(customStats);

            log.info(
                    "Migrated saved statistics from custom encounter {} to built-in encounter {}",
                    customEncounterId,
                    builtInEncounterId
            );
        }

        for (RecentDrop recentDrop : trackingData.getRecentDrops()) {
            if (recentDrop == null
                    || recentDrop.getEncounterId() == null
                    || !customEncounterId.equals(recentDrop.getEncounterId())) {
                continue;
            }

            recentDrop.migrateToEncounter(
                    builtInEncounterId,
                    builtInEncounter.getDisplayName(),
                    builtInEncounter.getImageUrl()
            );
        }

        /*
         * Custom drop selections belonged to the custom definition.
         *
         * The new built-in encounter should use its own configured
         * tracked drops and defaults instead.
         */
        trackingData.clearDropPreferences(customEncounterId);

        trackingData.removeCustomEncounter(customEncounterId);

        log.info(
                "Replaced custom encounter {} with built-in encounter {}",
                customEncounterId,
                builtInEncounterId
        );

        return true;
    }

    private boolean registerCustomEncounters() {
        if (trackingData == null) {
            return false;
        }

        boolean trackingDataChanged = false;

        for (EncounterDefinition encounter : new ArrayList<>(trackingData.getCustomEncounters())) {
            if (encounter == null
                    || encounter.getEncounterId() == null
                    || encounter.getEncounterId().trim().isEmpty()) {
                continue;
            }

            encounter.setLootType(EncounterLootType.GROUND_LOOT);

            EncounterDefinition conflictingEncounter = null;

            for (Integer npcId : encounter.getNpcIds()) {
                if (npcId == null) {
                    continue;
                }

                EncounterDefinition existing = encounterRegistry.getByNpcId(npcId);

                if (existing == null) {
                    continue;
                }

                /*
                 * Another saved custom encounter was registered earlier
                 * during this same load.
                 *
                 * This is not a built-in upgrade and must not trigger
                 * migration.
                 */
                if (trackingData.getCustomEncounter(existing.getEncounterId()) != null) {
                    log.warn(
                            "Custom encounter {} could not be loaded because NPC ID {} is already registered to custom encounter {}",
                            encounter.getEncounterId(),
                            npcId,
                            existing.getEncounterId()
                    );

                    conflictingEncounter = existing;

                    break;
                }

                /*
                 * The NPC ID now belongs to a built-in encounter.
                 *
                 * This can happen when encounters.json gains official
                 * support for an NPC which the player previously created
                 * as a custom encounter.
                 */
                conflictingEncounter = existing;

                log.info(
                        "Custom encounter {} now overlaps built-in encounter {} through NPC ID {}",
                        encounter.getEncounterId(),
                        existing.getEncounterId(),
                        npcId
                );

                break;
            }

            if (conflictingEncounter != null) {
                boolean builtInConflict =
                        trackingData.getCustomEncounter(conflictingEncounter.getEncounterId()) == null;

                if (builtInConflict
                        && migrateCustomEncounterToBuiltIn(encounter, conflictingEncounter)) {
                    trackingDataChanged = true;
                }

                continue;
            }

            try {
                encounterRegistry.register(encounter);
            } catch (Exception e) {
                log.warn("Could not register custom encounter {}", encounter.getEncounterId(), e);
            }
        }

        return trackingDataChanged;
    }

    private void unregisterCustomEncounters() {
        if (trackingData == null) {
            return;
        }

        List<EncounterDefinition> customEncounters =
                new ArrayList<>(trackingData.getCustomEncounters());

        for (EncounterDefinition encounter : customEncounters) {
            if (encounter == null || encounter.getEncounterId() == null) {
                continue;
            }

            encounterRegistry.unregister(encounter.getEncounterId());
        }
    }

    /**
     * Manually adds a missing tracked drop.
     *
     * This only updates the encounter's received drop totals and
     * creates a RecentDrop entry. Kill count and dry streak
     * statistics are intentionally left untouched.
     */
    public boolean addMissingDrop(String encounterId, int itemId, int quantity, int dropKillcount, long geValue) {
        if (!isActive()) {
            return false;
        }

        if (encounterId == null || encounterId.trim().isEmpty()) {
            return false;
        }

        if (itemId <= 0 || quantity <= 0 || dropKillcount <= 0) {
            return false;
        }

        EncounterDefinition definition = encounterRegistry.getById(encounterId);

        if (definition == null) {
            return false;
        }

        /*
         * Only items configured as tracked drops for this encounter
         * may be manually added.
         */
        if (definition.getTrackedDrop(itemId) == null) {
            return false;
        }

        /*
         * Respect the player's tracked-drop configuration.
         */
        if (!isDropEnabled(encounterId, itemId)) {
            return false;
        }

        EncounterStats stats = trackingData.getEncounter(encounterId);

        if (stats == null) {
            return false;
        }

        /*
         * Only update the received item totals.
         *
         * This intentionally does not touch KC, current dry streak,
         * longest dry streak, last completed dry streak, or any other
         * encounter progression.
         */
        stats.addMissingDrop(itemId, quantity);

        /*
         * Create a normal RecentDrop so the manually added item
         * appears in Recent Drops / submissions.
         */
        RecentDrop recentDrop = new RecentDrop(
                currentPlayerName,
                encounterId,
                definition.getDisplayName(),
                definition.getImageUrl(),
                itemId,
                quantity,
                dropKillcount,
                geValue,
                System.currentTimeMillis()
        );

        trackingData.addRecentDrop(recentDrop);

        save();

        log.info(
                "Manually added missing tracked drop {} x{} to {} with unique took {}",
                itemId,
                quantity,
                definition.getDisplayName(),
                dropKillcount
        );

        return true;
    }

}

package com.harrystyles.drystreaktracker.encounter.tracking;

public class RecentDrop {
    private String encounterId;

    private String encounterName;

    private String encounterImageUrl;

    private String playerName;

    private int itemId;

    private int quantity;

    private int dropKillcount;

    private int totalKillcount;

    private long geValue;

    private long acquiredAt;

    public RecentDrop() {
    }

    public RecentDrop(String playerName, String encounterId, String encounterName, String encounterImageUrl, int itemId, int quantity, int dropKillcount, long geValue, long acquiredAt) {
        this.playerName = playerName;
        this.encounterId = encounterId;
        this.encounterName = encounterName;
        this.encounterImageUrl = encounterImageUrl;
        this.itemId = itemId;
        this.quantity = quantity;
        this.dropKillcount = dropKillcount;
        this.geValue = geValue;
        this.acquiredAt = acquiredAt;
    }

    public String getPlayerName() {
        return playerName;
    }

    public String getEncounterId() {
        return encounterId;
    }

    public String getEncounterName() {
        return encounterName;
    }

    public String getEncounterImageUrl() {
        return encounterImageUrl;
    }

    public int getItemId() {
        return itemId;
    }

    public int getQuantity() {
        return quantity;
    }

    public int getDropKillcount() {
        return dropKillcount;
    }

    public int getTotalKillcount() {
        return totalKillcount;
    }

    public long getGeValue() {
        return geValue;
    }

    public long getAcquiredAt() {
        return acquiredAt;
    }

    public void migrateToEncounter(String encounterId, String encounterName, String encounterImageUrl) {
        if (encounterId == null || encounterId.trim().isEmpty()) {
            return;
        }

        this.encounterId = encounterId;
        this.encounterName = encounterName;
        this.encounterImageUrl = encounterImageUrl;
    }

}

package com.harrystyles.drystreaktracker.encounter.tracking;

import com.harrystyles.drystreaktracker.Constants;
import com.harrystyles.drystreaktracker.encounter.EncounterDefinition;
import com.harrystyles.drystreaktracker.encounter.EncounterStats;

import java.util.*;

/**
 * Stores all player-specific dry streak data.
 *
 * @author Harry Styles
 */
public class PlayerTrackingData {
    /**
     * Saved data format version.
     */
    private int version = 1;

    /**
     * Encounter statistics indexed by encounter ID.
     */
    private Map<String, EncounterStats> encounters = new HashMap<>();

    private List<RecentDrop> recentDrops = new ArrayList<>();

    /**
     * Player-created NPC encounter definitions.
     */
    private List<EncounterDefinition> customEncounters = new ArrayList<>();

    /**
     * Player-specific tracked drop overrides by encounter ID.
     *
     * Drops not explicitly enabled or disabled here follow
     * the defaults from the encounter definition.
     */
    private Map<String, EncounterDropPreferences> dropPreferences = new HashMap<>();

    public PlayerTrackingData() {
    }

    public int getVersion() {
        return version;
    }

    public void setVersion(int version) {
        this.version = version;
    }

    public Map<String, EncounterStats> getEncounters() {
        return encounters;
    }

    public List<RecentDrop> getRecentDrops() {
        if (recentDrops == null) {
            recentDrops = new ArrayList<>();
        }

        return recentDrops;
    }

    public void setEncounters(Map<String, EncounterStats> encounters) {
        this.encounters = encounters == null ? new HashMap<>() : encounters;
    }

    public void setRecentDrops(List<RecentDrop> recentDrops) {
        this.recentDrops = recentDrops == null ? new ArrayList<>() : new ArrayList<>(recentDrops);
    }

    public Map<String, EncounterDropPreferences> getDropPreferences() {
        if (dropPreferences == null) {
            dropPreferences = new HashMap<>();
        }

        return dropPreferences;
    }

    public EncounterDropPreferences getDropPreferences(String encounterId) {
        if (encounterId == null) {
            return new EncounterDropPreferences();
        }

        EncounterDropPreferences preferences = getDropPreferences().get(encounterId);

        return preferences != null ? preferences : new EncounterDropPreferences();
    }

    public EncounterDropPreferences getOrCreateDropPreferences(String encounterId) {
        if (encounterId == null) {
            return null;
        }

        EncounterDropPreferences preferences = getDropPreferences().get(encounterId);

        if (preferences == null) {
            preferences = new EncounterDropPreferences();

            getDropPreferences().put(encounterId, preferences);
        }

        return preferences;
    }

    public void clearDropPreferences(String encounterId) {
        if (encounterId == null) {
            return;
        }

        getDropPreferences().remove(encounterId);
    }

    public List<EncounterDefinition> getCustomEncounters() {
        if (customEncounters == null) {
            customEncounters = new ArrayList<>();
        }

        return customEncounters;
    }

    public EncounterDefinition getCustomEncounter(String encounterId) {
        if (encounterId == null) {
            return null;
        }

        for (EncounterDefinition encounter : getCustomEncounters()) {
            if (encounter != null && encounterId.equals(encounter.getEncounterId())) {
                return encounter;
            }
        }

        return null;
    }

    public EncounterDefinition getCustomEncounterByNpcId(int npcId) {
        for (EncounterDefinition encounter : getCustomEncounters()) {
            if (encounter != null && encounter.getNpcIds().contains(npcId)) {
                return encounter;
            }
        }

        return null;
    }

    public EncounterDefinition getCustomEncounterByNpc(String npcName, int combatLevel) {
        if (npcName == null || npcName.trim().isEmpty() || combatLevel <= 0) {
            return null;
        }

        String normalizedName = npcName.trim();

        for (EncounterDefinition encounter : getCustomEncounters()) {
            if (encounter == null
                    || encounter.getDisplayName() == null
                    || encounter.getCombatLevel() == null) {
                continue;
            }

            if (encounter.getDisplayName().trim().equalsIgnoreCase(normalizedName)
                    && encounter.getCombatLevel() == combatLevel) {
                return encounter;
            }
        }

        return null;
    }

    public void putCustomEncounter(EncounterDefinition encounter) {
        if (encounter == null || encounter.getEncounterId() == null) {
            return;
        }

        removeCustomEncounter(encounter.getEncounterId());

        getCustomEncounters().add(encounter);
    }

    public void removeCustomEncounter(String encounterId) {
        if (encounterId == null) {
            return;
        }

        getCustomEncounters().removeIf(encounter ->
                encounter != null && encounterId.equals(encounter.getEncounterId()));
    }

    public EncounterStats getEncounter(String encounterId) {
        if (encounterId == null) {
            return null;
        }

        return encounters.get(encounterId);
    }

    public void putEncounter(EncounterStats encounter) {
        if (encounter == null || encounter.getEncounterId() == null) {
            return;
        }

        encounters.put(encounter.getEncounterId(), encounter);
    }

    /**
     * Removes all saved statistics for one encounter.
     *
     * @param encounterId encounter to remove
     */
    public void removeEncounter(String encounterId) {
        if (encounterId == null || encounters == null) {
            return;
        }

        encounters.remove(encounterId);
    }

    public Collection<EncounterStats> getAllEncounters() {
        return encounters.values();
    }

    public boolean hasEncounter(String encounterId) {
        return encounterId != null && encounters.containsKey(encounterId);
    }

    public EncounterStats getOrCreateEncounter(EncounterDefinition definition) {
        if (definition == null || definition.getEncounterId() == null) {
            return null;
        }

        if (encounters == null) {
            encounters = new HashMap<>();
        }

        EncounterStats stats = encounters.get(definition.getEncounterId());

        if (stats == null) {
            stats = new EncounterStats(definition.getEncounterId(), definition.getDisplayName(), definition.getNpcIds());

            encounters.put(definition.getEncounterId(), stats);
        }

        return stats;
    }

    public void addRecentDrop(RecentDrop recentDrop) {
        if (recentDrop == null) {
            return;
        }

        getRecentDrops().add(0, recentDrop);

        while (recentDrops.size() > Constants.RECENT_DROPS_HISTORY_MAX_AMOUNT) {
            recentDrops.remove(recentDrops.size() - 1);
        }
    }

    public void clearRecentDrops() {
        getRecentDrops().clear();
    }

    public void removeRecentDrop(RecentDrop recentDrop) {
        if (recentDrop == null) {
            return;
        }

        getRecentDrops().remove(recentDrop);
    }

    public void clearEncounters() {
        encounters.clear();
    }

    @Override
    public String toString() {
        return "PlayerTrackingData{" +
                "version=" + version +
                ", encounters=" + encounters.size() +
                '}';
    }
}

package com.harrystyles.drystreaktracker.encounter.tracking;

import java.util.HashSet;
import java.util.Set;

/**
 * Stores player-specific overrides for an encounter's
 * configurable tracked drops.
 *
 * Items not present in either set use the default supplied
 * by the encounter definition.
 */
public class EncounterDropPreferences {
    private Set<Integer> enabled = new HashSet<>();

    private Set<Integer> disabled = new HashSet<>();

    public EncounterDropPreferences() {
    }

    public Set<Integer> getEnabled() {
        if (enabled == null) {
            enabled = new HashSet<>();
        }

        return enabled;
    }

    public Set<Integer> getDisabled() {
        if (disabled == null) {
            disabled = new HashSet<>();
        }

        return disabled;
    }

    public void setEnabled(Set<Integer> enabled) {
        this.enabled = enabled == null ? new HashSet<>() : new HashSet<>(enabled);
    }

    public void setDisabled(Set<Integer> disabled) {
        this.disabled = disabled == null ? new HashSet<>() : new HashSet<>(disabled);
    }
}

package com.harrystyles.drystreaktracker.encounter;

import com.harrystyles.drystreaktracker.encounter.EncounterDefinition;
import com.harrystyles.drystreaktracker.encounter.EncounterDropDefinition;
import com.harrystyles.drystreaktracker.encounter.EncounterLootType;
import com.harrystyles.drystreaktracker.encounter.tracking.EncounterTrackerManager;
import com.harrystyles.drystreaktracker.ui.CustomNpcTrackerDialog;
import com.harrystyles.drystreaktracker.ui.DryStreakSidebarPanel;
import com.harrystyles.drystreaktracker.wiki.WikiDropService;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.JOptionPane;
import javax.swing.SwingUtilities;

import lombok.extern.slf4j.Slf4j;

import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.client.game.ItemManager;

@Slf4j
@Singleton
public class CustomNpcEncounterService {
    private final EncounterTrackerManager trackerManager;
    private final WikiDropService wikiDropService;
    private final ItemManager itemManager;

    @Inject
    public CustomNpcEncounterService(EncounterTrackerManager trackerManager, WikiDropService wikiDropService, ItemManager itemManager) {
        this.trackerManager = trackerManager;
        this.wikiDropService = wikiDropService;
        this.itemManager = itemManager;
    }

    public void openTracker(DryStreakSidebarPanel sidebarPanel, String npcName, int npcId, int combatLevel, EncounterDefinition existingEncounter) {
        if (!trackerManager.isActive()) {
            return;
        }

        SwingUtilities.invokeLater(() -> {
            CustomNpcTrackerDialog dialog = new CustomNpcTrackerDialog(
                    sidebarPanel,
                    npcName,
                    npcId,
                    existingEncounter,
                    wikiDropService,
                    itemManager,
                    selectedItemIds ->
                            saveTracker(sidebarPanel, npcName, npcId, combatLevel, existingEncounter, selectedItemIds),
                    () -> {
                        if (existingEncounter != null) {
                            deleteTracker(sidebarPanel, existingEncounter.getEncounterId());
                        }
                    }
            );

            dialog.show();
        });
    }

    private void saveTracker(DryStreakSidebarPanel sidebarPanel, String npcName, int npcId, int combatLevel, EncounterDefinition existingEncounter, Set<Integer> selectedItemIds) {
        if (!trackerManager.isActive() || selectedItemIds == null) {
            return;
        }

        EncounterDefinition encounter = new EncounterDefinition();

        encounter.setEncounterId(existingEncounter != null
                ? existingEncounter.getEncounterId()
                : createEncounterId(npcId));

        encounter.setDisplayName(npcName);
        encounter.setCombatLevel(combatLevel);
        encounter.setLootType(EncounterLootType.GROUND_LOOT);

        String imageFileName = wikiDropService.getCachedNpcImageFileName(npcId);

        if (imageFileName != null && !imageFileName.trim().isEmpty()) {
            encounter.setImageFileName(imageFileName);
        } else if (existingEncounter != null) {
            encounter.setImageFileName(existingEncounter.getImageFileName());
        }

        Set<Integer> npcIds = new HashSet<>();

        if (existingEncounter != null) {
            npcIds.addAll(existingEncounter.getNpcIds());
        }

        npcIds.add(npcId);

        encounter.setNpcIds(npcIds);

        List<EncounterDropDefinition> trackedDrops = new ArrayList<>();

        for (Integer itemId : selectedItemIds) {
            if (itemId == null || itemId <= 0) {
                continue;
            }

            EncounterDropDefinition drop = new EncounterDropDefinition();

            drop.setItemId(itemId);
            drop.setEnabledByDefault(true);

            trackedDrops.add(drop);
        }

        /*
         * An empty tracked-drop list is valid.
         *
         * This allows custom encounters to be used only
         * for tracking kills.
         */
        encounter.setTrackedDrops(trackedDrops);

        /*
         * Custom encounters intentionally do not use LootReceived
         * source names or normal pet tracking.
         */
        encounter.setLootSourceNames(new HashSet<>());
        encounter.setPetDropIds(new HashSet<>());

        if (!trackerManager.saveCustomEncounter(encounter)) {
            SwingUtilities.invokeLater(() ->
                    JOptionPane.showMessageDialog(
                            sidebarPanel,
                            "Could not save the custom tracker for "
                                    + npcName
                                    + ".\n\nThis NPC may already belong to another encounter.",
                            "Custom NPC Tracker",
                            JOptionPane.ERROR_MESSAGE
                    )
            );

            return;
        }

        refreshSidebar(sidebarPanel);

        log.info(
                "Configured custom NPC tracker for {} ({}, combat {}) with {} tracked drops",
                npcName,
                npcId,
                combatLevel,
                trackedDrops.size()
        );
    }

    private void deleteTracker(DryStreakSidebarPanel sidebarPanel, String encounterId) {
        if (encounterId == null || encounterId.trim().isEmpty()) {
            return;
        }

        if (!trackerManager.removeCustomEncounter(encounterId)) {
            return;
        }

        refreshSidebar(sidebarPanel);
    }

    private void refreshSidebar(DryStreakSidebarPanel sidebarPanel) {
        if (sidebarPanel == null) {
            return;
        }

        SwingUtilities.invokeLater(() -> {
            sidebarPanel.refreshItemDisplayData();
            sidebarPanel.refresh();
        });
    }

    private String createEncounterId(int npcId) {
        return "custom_npc_" + npcId;
    }

    public boolean canCreateCustomTracker(NPC npc) {
        if (npc == null || npc.getCombatLevel() <= 0) {
            return false;
        }

        NPCComposition composition = npc.getTransformedComposition();

        if (composition == null) {
            composition = npc.getComposition();
        }

        if (composition == null || composition.getActions() == null) {
            return false;
        }

        for (String action : composition.getActions()) {
            if ("Attack".equalsIgnoreCase(action)) {
                return true;
            }
        }

        return false;
    }

}

package com.harrystyles.drystreaktracker;

import com.harrystyles.drystreaktracker.cosmetic.SmokeLootbeamManager;
import com.harrystyles.drystreaktracker.detection.LootDetectionService;
import com.harrystyles.drystreaktracker.encounter.*;
import com.harrystyles.drystreaktracker.encounter.tracking.EncounterTrackerManager;
import com.harrystyles.drystreaktracker.ui.DryStreakSidebarPanel;

import java.awt.image.BufferedImage;

import javax.inject.Inject;
import javax.swing.*;

import com.google.inject.Provides;

import com.harrystyles.drystreaktracker.wiki.WikiDropService;
import lombok.extern.slf4j.Slf4j;

import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.*;

import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(name = "Dry Streak Tracker", description = "Tracks your dry streaks at Pvm/Skilling content."
)
public class DryStreakTrackerPlugin extends Plugin {
    @Inject
    private EncounterRegistry encounterRegistry;

    @Inject
    private EncounterDefinitionLoader definitionLoader;

    @Inject
    private EncounterTrackerManager trackerManager;

    private LootDetectionService lootDetectionService;

    @Inject
    private CustomNpcEncounterService customNpcEncounterService;

    @Inject
    private SmokeLootbeamManager smokeLootbeamManager;

    @Inject
    private DryStreakTrackerConfig config;

    @Inject
    private ClientToolbar clientToolbar;

    private DryStreakSidebarPanel sidebarPanel;

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    private NavigationButton navigationButton;

    private boolean playerInitializationPending;

    @Provides
    DryStreakTrackerConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(DryStreakTrackerConfig.class);
    }

    @Override
    protected void startUp() {
        log.info("Dry Streak Tracker starting...");

        /*
         * Create Swing-dependent components after RuneLite's
         * UI/look-and-feel has been initialized.
         */
        sidebarPanel = injector.getInstance(DryStreakSidebarPanel.class);
        lootDetectionService = injector.getInstance(LootDetectionService.class);

        definitionLoader.loadInto(encounterRegistry);

        log.info("Loaded {} encounter definitions", encounterRegistry.size());

        trackerManager.start();

        BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/icon.png");

        navigationButton = NavigationButton.builder()
                .tooltip("Dry Streak Tracker")
                .icon(icon)
                .priority(5)
                .panel(sidebarPanel)
                .build();

        clientToolbar.addNavigation(navigationButton);

        sidebarPanel.setLoggedIn(false
        );

        if (client.getGameState() == GameState.LOGGED_IN) {
            playerInitializationPending = true;
        } else {
            SwingUtilities.invokeLater(() -> sidebarPanel.setLoggedIn(false));
        }

        log.info("Dry Streak Tracker started");
    }

    @Override
    protected void shutDown() {
        log.info("Dry Streak Tracker shutting down...");

        smokeLootbeamManager.clear();

        if (navigationButton != null) {
            clientToolbar.removeNavigation(navigationButton);

            navigationButton = null;
        }

        trackerManager.stop();

        encounterRegistry.clear();

        log.info("Dry Streak Tracker stopped");
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        if (event == null) {
            return;
        }

        GameState gameState = event.getGameState();

        if (gameState == GameState.LOGGED_IN) {
            playerInitializationPending = true;
            return;
        }

        if (gameState == GameState.LOGIN_SCREEN) {
            playerInitializationPending = false;

            smokeLootbeamManager.clear();
            lootDetectionService.clearProcessedLootEvents();
            trackerManager.stopForPlayer();

            SwingUtilities.invokeLater(() -> sidebarPanel.setLoggedIn(false));
        }
    }

    private void startCurrentPlayer() {
        Player player = client.getLocalPlayer();

        if (player == null) {
            return;
        }

        String playerName = player.getName();

        if (playerName == null || playerName.trim().isEmpty()) {
            return;
        }

        playerInitializationPending = false;

        log.info("Logged in as {}", playerName);

        trackerManager.startForPlayer(playerName);

        SwingUtilities.invokeLater(() -> {
            sidebarPanel.setLoggedIn(true);
            sidebarPanel.refresh();
        });

        sidebarPanel.refreshItemDisplayData();
    }

    /**
     * NPC loot.
     */
    @Subscribe
    public void onNpcLootReceived(NpcLootReceived event) {
        lootDetectionService.handleNpcLootReceived(event);
    }

    /**
     * Generic non-NPC loot.
     * <p>
     * The detection service ignores LootRecordType.NPC
     * to prevent duplicate processing.
     */
    @Subscribe
    public void onLootReceived(LootReceived event) {
        lootDetectionService.handleLootReceived(event);
    }

    /**
     * NPC deaths used to make GROUND_LOOT tracking independent
     * from whether the NPC actually produces loot.
     */
    @Subscribe
    public void onActorDeath(ActorDeath event) {
        lootDetectionService.handleActorDeath(event);
    }
    /**
     * Marks the end of a GROUND_LOOT NPC's death animation so
     * the no-loot fallback can safely begin.
     */
    @Subscribe
    public void onNpcDespawned(NpcDespawned event) {
        lootDetectionService.handleNpcDespawned(event);
    }
    @Subscribe
    public void onInteractingChanged(InteractingChanged event) {
        lootDetectionService.handleInteractingChanged(event);
    }


    /**
     * RuneScape game messages used for pet acquisition detection.
     */
    @Subscribe
    public void onChatMessage(ChatMessage event) {
        lootDetectionService.handlePetAcquisitionMessage(event);
    }

    /**
     * Processes dry results waiting for the pet acquisition
     * matching window to expire.
     */

    @Subscribe
    public void onGameTick(GameTick event) {
        if (playerInitializationPending && client.getGameState() == GameState.LOGGED_IN) {
            startCurrentPlayer();
        }

        lootDetectionService.processPendingGroundLootDeaths();
        lootDetectionService.processPendingPetDryResult();
    }

    @Subscribe
    public void onMenuEntryAdded(MenuEntryAdded event) {
        if (!config.customNpcTracking() || !trackerManager.isActive()) {
            return;
        }

        if (event == null || event.getMenuEntry() == null) {
            return;
        }

        MenuEntry menuEntry = event.getMenuEntry();

        /*
         * EXAMINE_NPC occurs once for the NPC's menu.
         *
         * Using it as the hook prevents us from adding the custom
         * option once for Attack, Talk-to, Examine, etc.
         */
        if (menuEntry.getType() != MenuAction.EXAMINE_NPC) {
            return;
        }

        NPC npc = menuEntry.getNpc();

        if (npc == null) {
            return;
        }

        String npcName = npc.getName();
        int npcId = npc.getId();
        int combatLevel = npc.getCombatLevel();

        if (npcName == null || npcName.trim().isEmpty() || npcId <= 0) {
            return;
        }

        /*
         * Custom trackers are intended for killable NPCs with an Attack option
         */
        if (!customNpcEncounterService.canCreateCustomTracker(npc)) {
            return;
        }

        EncounterDefinition registeredEncounter = encounterRegistry.getByNpcId(npcId);

        /*
         * An exact NPC ID already belongs to a built-in encounter.
         *
         * Built-in encounters always take priority over custom ones.
         */
        if (registeredEncounter != null
                && !trackerManager.isCustomEncounter(registeredEncounter.getEncounterId())) {
            return;
        }

        /*
         * Custom encounters first match the exact NPC ID.
         *
         * If this particular visual/ID variant has not been seen before,
         * fall back to exact NPC name + exact combat level.
         */
        EncounterDefinition customEncounter = trackerManager.getCustomEncounterByNpcId(npcId);

        if (customEncounter == null) {
            customEncounter = trackerManager.getCustomEncounterByNpc(npcName, combatLevel);
        }

        boolean customEncounterExists = customEncounter != null;

        String option = customEncounterExists
                ? "Configure Dry Streak Tracker"
                : "Add to Dry Streak Tracker";

        /*
         * Do not hold the NPC reference after the menu closes.
         */
        String selectedNpcName = npcName;
        int selectedNpcId = npcId;
        int selectedCombatLevel = combatLevel;
        EncounterDefinition selectedCustomEncounter = customEncounter;

        client.createMenuEntry(-1)
                .setOption(option)
                .setTarget(menuEntry.getTarget())
                .setType(MenuAction.RUNELITE)
                .onClick(clickedEntry ->
                        customNpcEncounterService.openTracker(
                                sidebarPanel,
                                selectedNpcName,
                                selectedNpcId,
                                selectedCombatLevel,
                                selectedCustomEncounter
                        ));
    }

    @Subscribe
    public void onItemSpawned(ItemSpawned event) {
        smokeLootbeamManager.handleItemSpawned(event);
    }

    @Subscribe
    public void onItemDespawned(ItemDespawned event) {
        smokeLootbeamManager.handleItemDespawned(event);
    }

